for _, child in ipairs(r:GetChildren()) do
if child:IsA("ScreenGui") and (child.Name == "atras_CustomUI" or child.Name == "atras_GUI" or child.Name == "ToggleUIButton") then
pcall(child.Destroy, child)
end
end
end
end)
