local __VNHUB_EN = {}
for enK, viV in pairs(__VNHUB_VI) do
	if type(viV) == "string" and viV ~= "" then
		__VNHUB_EN[viV] = enK
	end
end
__VNHUB_EN["Trộm Trứng"] = "Steal Eggs"
__VNHUB_EN["Tự Động Farm"] = "Auto Farm"
__VNHUB_EN["Trứng"] = "Eggs"
__VNHUB_EN["Sự Kiện"] = "Events"
__VNHUB_EN["Cài Đặt"] = "Settings"
__VNHUB_EN["Tắt"] = "Off"
__VNHUB_EN["Tắt ($0/s)"] = "Off ($0/s)"

if type(_G.__VNHUB_LANG) ~= "string" then
	local savedLang = "VI"
	pcall(function()
		if type(isfile) == "function" and type(readfile) == "function" and isfile("VNHUB_SAE/lang.txt") then
			local raw = tostring(readfile("VNHUB_SAE/lang.txt") or ""):match("^%s*(.-)%s*$")
			if raw == "EN" or raw == "VI" then
				savedLang = raw
			end
		end
	end)
	_G.__VNHUB_LANG = savedLang
end

local function __VNHUB_TO_VI(s)
if type(s) ~= "string" or s == "" then
return s
end
local direct = __VNHUB_VI[s]
if direct then
return direct
end
local trimmed = s:match("^%s*(.-)%s*$")
if trimmed and __VNHUB_VI[trimmed] then
return __VNHUB_VI[trimmed]
end
local m1, m2 = s:match("^Active %((.+)%)$")
if m1 then
return "Đang chạy (" .. __VNHUB_TO_VI(m1) .. ")"
end
m1 = s:match("^Waiting %((.+)%)$")
if m1 then
return "Đang chờ (" .. __VNHUB_TO_VI(m1) .. ")"
end
m1 = s:match("^Steal: (.+)$")
if m1 then
return "Trộm: " .. __VNHUB_TO_VI(m1)
end
m1 = s:match("^Wait (.+)$")
if m1 then
return "Chờ " .. m1
end
m1 = s:match("^Next in (.+)$")
if m1 then
return "Tiếp theo sau " .. m1
end
m1 = s:match("^Cooldown (.+)$")
if m1 then
return "Hồi chiêu " .. m1
end
m1 = s:match("^Place (.+)$")
if m1 then
return "Đặt " .. m1
end
m1 = s:match("^Need (.+)$")
if m1 then
return "Cần " .. m1
end
m1 = s:match("^Scan (.+)$")
if m1 then
return "Quét " .. m1
end
m1 = s:match("^Feed (.+)$")
if m1 then
return "Nạp " .. m1
end
m1 = s:match("^~(%d+)s left$")
if m1 then
return "Còn ~" .. m1 .. "s"
end
m1 = s:match("^(%d+) Drone%(s%) in field$")
if m1 then
return m1 .. " Drone trên sân"
end
m1, m2 = s:match("^x([%d%.]+)  •  (.+)$")
if m1 and m2 then
return "x" .. m1 .. "  •  " .. __VNHUB_TO_VI(m2)
end
m1, m2 = s:match("^Tier (%d+): (.+)$")
if m1 and m2 then
return "Bậc " .. m1 .. ": " .. __VNHUB_TO_VI(m2)
end
m1 = s:match("^Floor (%d+)$")
if m1 then
return "Tầng " .. m1
end
m1, m2 = s:match("^(%d+) of (%d+) unlocked$")
if m1 and m2 then
return "Đã mở khóa " .. m1 .. "/" .. m2
end
m1 = s:match("^(%d+) owned$")
if m1 then
return "Đang có " .. m1
end
m1 = s:match("^(%d+) eggs?$")
if m1 then
return m1 .. " trứng"
end
m1 = s:match("^(%d+) pets?$")
if m1 then
return m1 .. " thú cưng"
end
m1 = s:match("^(%d+) match(es)?$")
if m1 then
return m1 .. " kết quả"
end
m1 = s:match("^Current Auto%-Load: (.+)$")
if m1 then
return "Tự động tải hiện tại: " .. (m1 == "None" and "Không có" or m1)
end
if s:find("Walk Speed") or s:find("speed") or s:find("Placed:") or s:find("Stage ") or s:find("State:") or s:find("Stars:") or s:find("Scrambled") or s:find("Owned Eggs:") or s:find("JobId:") or s:find("Active:") or s:find("Souls:") or s:find("Bloom") or s:find("Wisp") or s:find("Boss") then
s = s:gsub("Walk Speed is still loading%.%.%.", "Đang tải chỉ số tốc độ chạy...")
s = s:gsub("Your Walk Speed is ([%d%.]+) %(below 500%)%. Turn ON Low Speed User and set Low Speed Multiplier around (%d+)%. Raise the multiplier if your speed is closer to 500, or lower it if steals fail%.", "Tốc độ chạy của bạn là %1 (dưới 500). Hãy BẬT Chế Độ Tốc Độ Thấp và chỉnh Hệ Số khoảng %2 (hoặc kéo Max 10 để Dịch Chuyển Tức Thì).")
s = s:gsub("Your Walk Speed is ([%d%.]+) %(500%+%)%. Turn ON High Speed User and pick a Steal Mode %(Walk, Glide, Zigzag, Fly, or Booster%)%.", "Tốc độ chạy của bạn là %1 (trên 500). Hãy BẬT Chế Độ Tốc Độ Cao và chọn Kiểu Di Chuyển (hoặc kéo Max tốc độ để Dịch Chuyển Tức Thì).")
s = s:gsub("Placed: (%d+)  |  Hatching: (%d+)  |  Ready: (%d+)  |  Empty: (%d+)", "Đã đặt: %1  |  Đang ấp: %2  |  Sẵn sàng: %3  |  Ô trống: %4")
s = s:gsub("Event inactive  |  Buds: ", "Sự kiện chưa mở  |  Mầm hoa: ")
s = s:gsub("Stage (%d+/%d+)", "Giai đoạn %1")
s = s:gsub("Buds: ", "Mầm hoa: ")
s = s:gsub("Runtime: ", "Hoạt động: ")
s = s:gsub("State: ", "Trạng thái: ")
s = s:gsub("Course: ", "Đường đua: ")
s = s:gsub("Position: ", "Vị trí: ")
s = s:gsub("Checkpoint: ", "Điểm mốc: ")
s = s:gsub("Starts In: ", "Bắt đầu sau: ")
s = s:gsub("Ends In: ", "Kết thúc sau: ")
s = s:gsub("Prompt: ", "Báo danh: ")
s = s:gsub("Stars: ", "Sao: ")
s = s:gsub("Shop Reset: ", "Làm mới tiệm: ")
