local function __VNHUB_TO_EN(s)
if type(s) ~= "string" or s == "" then
return s
end
local direct = __VNHUB_EN[s]
if direct then
return direct
end
local trimmed = s:match("^%s*(.-)%s*$")
if trimmed and __VNHUB_EN[trimmed] then
return __VNHUB_EN[trimmed]
end
local m1 = s:match("^Đang chạy %((.+)%)$")
if m1 then
return "Active (" .. __VNHUB_TO_EN(m1) .. ")"
end
m1 = s:match("^Đang chờ %((.+)%)$")
if m1 then
return "Waiting (" .. __VNHUB_TO_EN(m1) .. ")"
end
m1 = s:match("^Trộm: (.+)$")
if m1 then
return "Steal: " .. __VNHUB_TO_EN(m1)
end
m1 = s:match("^(.-) đã trộm$")
if m1 then
return m1 .. " stolen"
end
if s:find("Đang đặt:") or s:find("Người chơi khác:") or s:find("Trứng xịn nhất sân:") or s:find("SẴN SÀNG NỞ") or s:find("⏳ Còn ") or s:find("Thường %(x") then
s = s:gsub("🥚 Đang đặt: (%d+/%d+) quả  •  ✅ Sẵn sàng nở: (%d+) quả\n💰 Tổng thu nhập dự đoán: (.-)  •  ⚖️ Quả nặng nhất: (.+)", "🥚 Placed: %1 eggs  •  ✅ Ready: %2 eggs\n💰 Est. Total Income: %3  •  ⚖️ Heaviest: %4")
s = s:gsub("👥 Người chơi khác: (%d+) %(Tổng: (%d+/%d+)%)  •  Mục tiêu <= (.-) người khác\n⚡ (.+)", "👥 Other players: %1 (Total: %2)  •  Target <= %3 others\n⚡ %4")
s = s:gsub("🔥 Trứng xịn nhất sân: (.-)\n🎯 Khớp bộ lọc săn: (%d+) quả  •  Độ hiếm >= (.-)  •  Giá trị >= (.-)\n⚡ Trạng thái: (.+)", "🔥 Best field egg: %1\n🎯 Matching filter: %2 eggs  •  Rarity >= %3  •  Value >= %4\n⚡ Status: %5")
s = s:gsub("✅ SẴN SÀNG NỞ!", "✅ READY TO HATCH!")
s = s:gsub("⏳ Còn ", "⏳ ")
s = s:gsub("🧬 Thường %(x", "🧬 Normal (x")
s = s:gsub("Sẵn sàng", "Ready")
s = s:gsub("Đã tắt", "Off")
s = s:gsub("Không có", "None")
end
return s
end

local function __VNHUB_TR(s)
if _G.__VNHUB_LANG == "EN" then
return __VNHUB_TO_EN(s)
end
return __VNHUB_TO_VI(s)
end
