local function getGuiParent()
	local ok, hui = pcall(function()
		if type(gethui) == "function" then
			return gethui()
		end
		return nil
	end)
	if ok and hui then
		return hui
	end
	local ok2, cg = pcall(function()
		return CoreGui
	end)
	if ok2 and cg then
		return cg
	end
	if LocalPlayer then
		return LocalPlayer:FindFirstChildOfClass("PlayerGui")
	end
	return nil
end

