local function resolveAsset(icon, fallback)
	if type(icon) ~= "string" or icon == "" then
		return fallback or ""
	end
	local trimmed = icon:match("^%s*(.-)%s*$") or icon
	if Icons[icon] then
		return Icons[icon]
	end
	if Icons[trimmed] then
		return Icons[trimmed]
	end
	if trimmed:find("^rbxassetid://") or trimmed:find("^rbxasset://") or trimmed:find("^https?://") then
		return trimmed
	end
	if tonumber(trimmed) then
		return "rbxassetid://" .. trimmed
	end
	local sharedAssets = rawget(_G, "__VNHUB_SHARED_ASSETS")
	if type(sharedAssets) == "table" and type(sharedAssets. resolve) == "function" then
		local ok, res = pcall(sharedAssets.resolve, trimmed, fallback)
		if ok and type(res) == "string" and res ~= "" then
			return res
		end
	end
	return fallback or Icons.info
end

local function syncInstLanguage(inst)
	if not inst or inst:GetAttribute("VNHUB_SkipLang") == true then return end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") then
		local cur = inst.Text
		if type(cur) == "string" and cur ~= "" and cur ~= "—" and cur ~= "✕" and cur ~= "+" and cur ~= "-" and cur ~= "✓" then
			local last = inst:GetAttribute("VNHUB_LastText")
			local viStr = inst:GetAttribute("VNHUB_VI")
			local enStr = inst:GetAttribute("VNHUB_EN")
			if cur ~= last or type(viStr) ~= "string" or type(enStr) ~= "string" then
				viStr = __VNHUB_TO_VI(cur)
				enStr = __VNHUB_TO_EN(cur)
				inst:SetAttribute("VNHUB_VI", viStr)
				inst:SetAttribute("VNHUB_EN", enStr)
			end
			local target = (_G.__VNHUB_LANG == "EN") and enStr or viStr
			inst:SetAttribute("VNHUB_LastText", target)
			if inst.Text ~= target then
				inst.Text = target
			end
		end
	elseif inst:IsA("TextBox") then
		local pCur = inst.PlaceholderText
		if type(pCur) == "string" and pCur ~= "" then
			local pLast = inst:GetAttribute("VNHUB_LastPlaceholder")
			local pVi = inst:GetAttribute("VNHUB_P_VI")
			local pEn = inst:GetAttribute("VNHUB_P_EN")
			if pCur ~= pLast or type(pVi) ~= "string" or type(pEn) ~= "string" then
				pVi = __VNHUB_TO_VI(pCur)
				pEn = __VNHUB_TO_EN(pCur)
				inst:SetAttribute("VNHUB_P_VI", pVi)
				inst:SetAttribute("VNHUB_P_EN", pEn)
			end
			local pTarget = (_G.__VNHUB_LANG == "EN") and pEn or pVi
			inst:SetAttribute("VNHUB_LastPlaceholder", pTarget)
			if inst.PlaceholderText ~= pTarget then
				inst.PlaceholderText = pTarget
			end
		end
	end
end

local function create(className, props, children)
	local inst = Instance.new(className)
	if props then
		for k, v in pairs(props) do
			if k ~= "Parent" then
				pcall(function()
					inst[k] = v
				end)
			end
		end
	end
	if children then
		for _, child in ipairs(children) do
			if child then
				child.Parent = inst
			end
		end
	end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
		local syncing = false
		syncInstLanguage(inst)
		if inst:IsA("TextLabel") or inst:IsA("TextButton") then
			inst:GetPropertyChangedSignal("Text"):Connect(function()
				if syncing then return end
				syncing = true
				pcall(syncInstLanguage, inst)
				syncing = false
			end)
		end
	end
	if props and props.Parent then
		inst.Parent = props.Parent
	end
	return inst
end

local function addCorner(parent, radius)
	return create("UICorner", {
		CornerRadius = UDim.new(0, radius or 8),
		Parent = parent,
	})
end

local function addStroke(parent, color, thickness, transparency)
	return create("UIStroke", {
		Color = color or Theme.Border,
		Thickness = thickness or 1,
		Transparency = transparency or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = parent,
	})
end

local function addPadding(parent, top, bottom, left, right)
	return create("UIPadding", {
		PaddingTop = UDim.new(0, top or 0),
		PaddingBottom = UDim.new(0, bottom or 0),
		PaddingLeft = UDim.new(0, left or 0),
		PaddingRight = UDim.new(0, right or 0),
		Parent = parent,
	})
end

local function tween(inst, duration, props, style, dir)
	if not inst then
		return nil
	end
	local ok, tw = pcall(function()
		local info = TweenInfo.new(
			duration or 0.16,
			style or Enum.EasingStyle.Quad,
			dir or Enum.EasingDirection.Out
		)
		local t = TweenService:Create(inst, info, props)
		t:Play()
		return t
	end)
	return ok and tw or nil
end

local function safeCallback(fn, ...)
	if type(fn) ~= "function" then
		return
	end
	local args = { ... }
	local ok, err = pcall(function()
		fn(unpack(args))
	end)
	if not ok then
		warn("[VN HUB UI Callback Error]:", err)
	end
end

local function connectClick(button, callback)
	if not button then return end
	local lastTrigger = 0
	local function trigger(...)
		local now = tick()
		if now - lastTrigger < 0.08 then return end
		lastTrigger = now
		callback(...)
	end
	local act = button.Activated
	if act and act.Connect then
		act:Connect(trigger)
	end
	local clk = button.MouseButton1Click
	if clk and clk.Connect then
		clk:Connect(trigger)
	end
end

local function sanitizeKey(str)
	local s = tostring(str or "Item")
	s = s:gsub("[%c%p%s]+", "_")
	s = s:gsub("^_+", ""):gsub("_+$", "")
	if s == "" then
		return "Item"
	end
	return s
end

local function cloneValue(val)
	if type(val) ~= "table" then
		return val
	end
	local copy = {}
	for k, v in pairs(val) do
		copy[k] = cloneValue(v)
	end
	return copy
end

local function copyArray(list)
	local out = {}
	if type(list) == "table" then
		for i, v in ipairs(list) do
			out[i] = v
		end
	end
	return out
end

local function estimateLines(text, charsPerLine)
	local s = tostring(text or "")
	if s == "" then
		return 0
	end
	local cpl = math.max(15, charsPerLine or 52)
	local count = 0
	for line in (s .. "\n"):gmatch("(.-)\n") do
		count = count + math.max(1, math.ceil(#line / cpl))
	end
	return math.max(1, count)
end

-- ============================================================================
-- CONFIG SYSTEM (File-backed JSON persistence + schema v2 validation)
-- ============================================================================
local MISSING_DEFAULT = "__VNHUB_MISSING_DEFAULT__"
local CONFIG_SCHEMA_VERSION = 5

local Config = {
	folder = "VNHUB",
	sub = "VNHUB_SAE",
	name = "AutoSave",
	auto = true,
	data = { _vnhub_schema = CONFIG_SCHEMA_VERSION },
	defaults = {},
	setters = {},
	getters = {},
	resetters = {},
	_saveQueued = false,
}

function Config:canUseFS()
	return type(isfolder) == "function"
		and type(makefolder) == "function"
		and type(writefile) == "function"
		and type(readfile) == "function"
		and type(isfile) == "function"
end

function Config:ensureFolders()
	if not self:canUseFS() then
		return false
	end
	pcall(function()
		if not isfolder(self.folder) then
			makefolder(self.folder)
		end
		local subPath = self.folder .. "/" .. self.sub
		if not isfolder(subPath) then
			makefolder(subPath)
		end
	end)
	return true
end

function Config:path(cfgName)
	local n = sanitizeKey(cfgName or self.name or "AutoSave")
	return self.folder .. "/" .. self.sub .. "/" .. n .. ".json"
end

function Config:setup(opts)
	opts = type(opts) == "table" and opts or {}
	self.folder = tostring(opts.Folder or opts.ConfigFolder or "VNHUB")
	self.sub = sanitizeKey(opts.SubFolder or opts.Name or opts.Title or "VNHUB_SAE")
	self.name = sanitizeKey(opts.ConfigName or opts.DefaultConfig or "AutoSave")
	self.auto = opts.AutoSave ~= false
	self.data = { _vnhub_schema = CONFIG_SCHEMA_VERSION }
	self.defaults = {}
	self.setters = {}
	self.getters = {}
	self.resetters = {}
	self:ensureFolders()
	if opts.AutoLoad ~= false then
		self:load(self.name, true)
	end
end

function Config:pack()
	local payload = { _vnhub_schema = CONFIG_SCHEMA_VERSION }
	for k, v in pairs(self.data) do
		payload[k] = cloneValue(v)
	end
	for k, getter in pairs(self.getters) do
		local ok, val = pcall(getter)
		if ok then
			payload[k] = cloneValue(val)
		end
	end
	payload._vnhub_schema = CONFIG_SCHEMA_VERSION
	return payload
end

function Config:save(cfgName)
	if not self:ensureFolders() then
		return false
	end
	local path = self:path(cfgName)
	local ok, encoded = pcall(function()
		return HttpService:JSONEncode(self:pack())
	end)
	if not ok or type(encoded) ~= "string" then
		return false
	end
	local okWrite = pcall(writefile, path, encoded)
	return okWrite == true
end

function Config:scheduleSave()
	if not self.auto or self._saveQueued then
		return
	end
	self._saveQueued = true
	task.delay(0.25, function()
		self._saveQueued = false
		self:save(self.name)
	end)
end

function Config:loadelements()
	for k, v in pairs(self.data) do
		if k ~= "_vnhub_schema" and self.setters[k] then
			pcall(self.setters[k], cloneValue(v))
		end
	end
end

function Config:load(cfgName, silent)
	if not self:canUseFS() then
		return false
	end
	local path = self:path(cfgName)
	local okFile, exists = pcall(isfile, path)
	if not okFile or not exists then
		return false
	end
	local okRead, raw = pcall(readfile, path)
	if not okRead or type(raw) ~= "string" or raw == "" then
		return false
	end
	local okDec, decoded = pcall(function()
		return HttpService:JSONDecode(raw)
	end)
	if not okDec or type(decoded) ~= "table" then
		return false
	end
	-- Ignore corrupted configs saved by older schema versions
	if decoded._vnhub_schema ~= CONFIG_SCHEMA_VERSION then
		self.data = { _vnhub_schema = CONFIG_SCHEMA_VERSION }
		return false
	end
	self.data = decoded
	if not silent then
		self:loadelements()
	end
	return true
end

function Config:delete(cfgName)
	if type(delfile) ~= "function" then
		return false
	end
	local path = self:path(cfgName)
	local ok, exists = pcall(isfile, path)
	if ok and exists then
		pcall(delfile, path)
		return true
	end
	return false
end

function Config:reset()
	self.data = { _vnhub_schema = CONFIG_SCHEMA_VERSION }
	for k, def in pairs(self.defaults) do
		local restored = nil
		if def ~= MISSING_DEFAULT then
			restored = cloneValue(def)
		end
		if restored ~= nil then
			self.data[k] = cloneValue(restored)
		end
		if self.resetters[k] then
			pcall(self.resetters[k], cloneValue(restored))
		elseif self.setters[k] then
			pcall(self.setters[k], cloneValue(restored))
		end
	end
	self:save(self.name)
	return true
end

function Config:list()
	local out = { self.name }
	if type(listfiles) == "function" and self:ensureFolders() then
		local ok, files = pcall(listfiles, self.folder .. "/" .. self.sub)
		if ok and type(files) == "table" then
			local seen = { [self.name] = true }
			for _, f in ipairs(files) do
				local name = tostring(f):match("([^/\\]+)%.json$")
				if name and not seen[name] then
					seen[name] = true
					table.insert(out, name)
				end
			end
		end
	end
	return out
end

function Config:register(key, defaultVal, setter, getter, resetter)
	if defaultVal == nil then
		self.defaults[key] = MISSING_DEFAULT
	else
		self.defaults[key] = cloneValue(defaultVal)
	end
	self.setters[key] = setter
	self.getters[key] = getter
	self.resetters[key] = resetter
	local hasPref = self.data[key] ~= nil
	local prefVal
	if hasPref then
		prefVal = cloneValue(self.data[key])
	else
		prefVal = cloneValue(defaultVal)
		if defaultVal ~= nil then
			self.data[key] = cloneValue(defaultVal)
		end
	end
	return hasPref, prefVal
end

