local NotifyHolder = nil

local function ensureNotifyHolder(parentGui)
	if NotifyHolder and NotifyHolder.Parent then
		return NotifyHolder
	end
	local host = parentGui or getGuiParent()
	if not host then
		return nil
	end
	local screen = host:FindFirstChild("VNHUB_NotifyGui")
	if not screen then
		screen = create("ScreenGui", {
			Name = "VNHUB_NotifyGui",
			ResetOnSpawn = false,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = 999,
			Parent = host,
		})
	end
	NotifyHolder = create("Frame", {
		Name = "NotifyHolder",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -18, 1, -18),
		Size = UDim2.new(0, 310, 1, -36),
		BackgroundTransparency = 1,
		Parent = screen,
	}, {
		create("UIListLayout", {
			SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			Padding = UDim.new(0, 8),
		}),
	})
	return NotifyHolder
end

local Library = {}

function Library:MakeNotify(opts)
	opts = type(opts) == "table" and opts or {}
	local title = tostring(opts.Title or "VN HUB")
	local desc = tostring(opts.Description or "")
	local content = tostring(opts.Content or "")
	local duration = tonumber(opts.Delay or opts.Time or opts.Duration) or 4
	local accent = opts.Color or Theme.Accent

	local holder = ensureNotifyHolder()
	if not holder then
		return
	end

	local bodyText = content ~= "" and content or desc
	local subTitle = (content ~= "" and desc ~= "") and desc or nil
	local lines = estimateLines(bodyText, 38)
	local cardH = math.clamp(48 + lines * 16 + (subTitle and 16 or 0), 62, 160)

	local card = create("Frame", {
		Size = UDim2.new(1, 0, 0, cardH),
		BackgroundColor3 = Theme.BgCard,
		BackgroundTransparency = 0.04,
		ClipsDescendants = true,
		Parent = holder,
	})
	addCorner(card, 10)
	addStroke(card, accent, 1, 0.25)

	create("Frame", {
		Size = UDim2.new(0, 4, 1, 0),
		BackgroundColor3 = accent,
		BorderSizePixel = 0,
		Parent = card,
	})

	create("TextLabel", {
		Position = UDim2.new(0, 14, 0, 8),
		Size = UDim2.new(1, -24, 0, 18),
		BackgroundTransparency = 1,
		Font = Theme.FontBold,
		Text = title,
		TextColor3 = Theme.TextPrimary,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = card,
	})

	local textTop = 28
	if subTitle then
		create("TextLabel", {
			Position = UDim2.new(0, 14, 0, 26),
			Size = UDim2.new(1, -24, 0, 15),
			BackgroundTransparency = 1,
			Font = Theme.FontSemi,
			Text = subTitle,
			TextColor3 = accent,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = card,
		})
		textTop = 43
	end

	create("TextLabel", {
		Position = UDim2.new(0, 14, 0, textTop),
		Size = UDim2.new(1, -24, 1, -(textTop + 8)),
		BackgroundTransparency = 1,
		Font = Theme.FontReg,
		Text = bodyText,
		TextColor3 = Theme.TextSecondary,
		TextSize = 12,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Parent = card,
	})

	task.delay(math.max(0.5, duration), function()
		if card and card.Parent then
			tween(card, 0.2, { BackgroundTransparency = 1 })
			task.wait(0.22)
			if card and card.Parent then
				card:Destroy()
			end
		end
	end)
end

function Library:Notify(opts)
	return self:MakeNotify(opts)
end

