	local function setLanguageMode(langCode)
		if _G.__VNHUB_LANG == langCode then return end
		_G.__VNHUB_LANG = langCode
		pcall(function()
			if type(writefile) == "function" then
				if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder("VNHUB_SAE") then
					pcall(makefolder, "VNHUB_SAE")
				end
				writefile("VNHUB_SAE/lang.txt", _G.__VNHUB_LANG)
			end
		end)
		updateFlagButtonsStyle()
		local roots = { screenGui }
		local gp = getGuiParent()
		if gp then
			for _, ch in ipairs(gp:GetChildren()) do
				if ch:IsA("ScreenGui") and ch ~= screenGui then
					table.insert(roots, ch)
				end
			end
		end
		for _, rGui in ipairs(roots) do
			for _, desc in ipairs(rGui:GetDescendants()) do
				pcall(syncInstLanguage, desc)
			end
		end
		Library:Notify({
			Title = "VN HUB 🇻🇳",
			Content = (langCode == "EN") and "🇺🇸 Switched language to English!" or "🇻🇳 Đã chuyển ngôn ngữ sang Tiếng Việt!",
			Duration = 2.5,
