	-- Dragging helper (supports Mouse & Touch)
	local function makeDraggable(handle, targetFrame, onClick)
		local dragging = false
		local dragInput = nil
		local dragStart = nil
		local startPos = nil
		local moved = false

		handle.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				moved = false
				dragStart = input.Position
				startPos = targetFrame.Position
				input.Changed:Connect(function()
					if input.UserInputState == Enum.UserInputState.End then
						if dragging and not moved and type(onClick) == "function" then
							onClick()
						end
						dragging = false
					end
				end)
			end
		end)

		handle.InputChanged:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				dragInput = input
			end
		end)

		UserInputService.InputChanged:Connect(function(input)
			if input == dragInput and dragging and dragStart and startPos then
				local delta = input.Position - dragStart
				if delta.Magnitude > 5 then
					moved = true
				end
				targetFrame.Position = UDim2.new(
					startPos.X.Scale,
					startPos.X.Offset + delta.X,
					startPos.Y.Scale,
					startPos.Y.Offset + delta.Y
				)
			end
		end)
	end

	makeDraggable(topBar, mainFrame, nil)
	makeDraggable(floatBtn, floatBtn, function()
		setWindowVisible(not windowVisible)
	end)

	local toggleKey = winOpts.ToggleKey or Enum.KeyCode.RightControl
	UserInputService.InputBegan:Connect(function(input, gp)
		if not gp and input.KeyCode == toggleKey then
			setWindowVisible(not windowVisible)
		end
	end)

