	local tabs = {}
	local activeTab = nil

	local function selectTab(tabEntry)
		if not tabEntry then
			return
		end
		activeTab = tabEntry
		for _, t in ipairs(tabs) do
			local isSelected = (t == tabEntry)
			t.Page.Visible = isSelected
			t.Indicator.Visible = isSelected
			tween(t.Button, 0.15, {
				BackgroundColor3 = isSelected and Theme.BgCardHover or Theme.BgCard,
				BackgroundTransparency = isSelected and 0 or 0.45,
			})
			t.TitleLabel.TextColor3 = isSelected and Theme.TextPrimary or Theme.TextSecondary
			t.IconLabel.ImageColor3 = isSelected and Theme.Accent or Theme.TextMuted
			t.Stroke.Color = isSelected and Theme.BorderAccent or Theme.Border
			t.Stroke.Transparency = isSelected and 0.2 or 0.55
		end
	end

	-- ========================================================================
	-- SECTION ELEMENT ATTACHERS (100% compatible with vnhub.delta.luau)
