	local function attachElementsToContainer(containerObj, itemHolder, sectionPrefix)
		local elemOrder = 0
		local function nextOrder()
			elemOrder = elemOrder + 1
			return elemOrder
		end

		local function makeLockOverlay(cardFrame)
			local overlay = create("TextButton", {
				Name = "LockOverlay",
				Size = UDim2.new(1, 0, 1, 0),
