				RichText = true,
				Visible = titleText ~= "",
				Parent = card,
			})

			local contentLbl = create("TextLabel", {
				Position = UDim2.new(0, 12, 0, titleText ~= "" and 28 or 8),
				Size = UDim2.new(1, -24, 0, 20),
				BackgroundTransparency = 1,
				Font = Theme.FontReg,
				Text = bodyText,
				TextColor3 = Theme.TextSecondary,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				TextWrapped = true,
				RichText = true,
				Visible = bodyText ~= "",
				Parent = card,
			})

			local btnRow = nil
			if type(btnText) == "string" and btnText ~= "" then
				btnRow = create("Frame", {
					Position = UDim2.new(0, 12, 1, -34),
					Size = UDim2.new(1, -24, 0, 26),
					BackgroundTransparency = 1,
					Parent = card,
				})
				local b1 = create("TextButton", {
					Size = subBtnText and UDim2.new(0.5, -4, 1, 0) or UDim2.new(1, 0, 1, 0),
					BackgroundColor3 = Theme.AccentDark,
					Font = Theme.FontBold,
					Text = tostring(btnText),
					TextColor3 = Theme.TextPrimary,
					TextSize = 12,
					AutoButtonColor = false,
					Parent = btnRow,
				})
				addCorner(b1, 6)
				connectClick(b1, function()
					safeCallback(btnCallback)
				end)

				if type(subBtnText) == "string" and subBtnText ~= "" then
					local b2 = create("TextButton", {
						Position = UDim2.new(0.5, 4, 0, 0),
						Size = UDim2.new(0.5, -4, 1, 0),
						BackgroundColor3 = Theme.BgSecondary,
						Font = Theme.FontBold,
						Text = tostring(subBtnText),
						TextColor3 = Theme.TextPrimary,
						TextSize = 12,
						AutoButtonColor = false,
						Parent = btnRow,
					})
					addCorner(b2, 6)
					addStroke(b2, Theme.Border, 1, 0.25)
					connectClick(b2, function()
						safeCallback(subBtnCallback)
					end)
				end
			end

			local function recalcHeight()
				local tLines = titleText ~= "" and estimateLines(titleText, 50) or 0
				local cLines = bodyText ~= "" and estimateLines(bodyText, 54) or 0
				local tH = tLines > 0 and (tLines * 18) or 0
				local cH = cLines > 0 and (cLines * 16 + 4) or 0
				titleLbl.Visible = tLines > 0
				titleLbl.Size = UDim2.new(1, -24, 0, tH)
				local cTop = tH > 0 and (10 + tH) or 8
				contentLbl.Visible = cLines > 0
				contentLbl.Position = UDim2.new(0, 12, 0, cTop)
				contentLbl.Size = UDim2.new(1, -24, 0, cH)
				local total = cTop + cH + 10
				if btnRow then
					btnRow.Position = UDim2.new(0, 12, 0, total)
					total = total + 34
				end
				card.Size = UDim2.new(1, 0, 0, math.max(38, total))
			end
			recalcHeight()

			local obj = {
				Frame = card,
				Title = titleText,
				Content = bodyText,
			}
			function obj:SetTitle(newTitle)
				titleText = tostring(newTitle or "")
				self.Title = titleText
				titleLbl.Text = titleText
				recalcHeight()
			end
			function obj:SetContent(newContent)
				bodyText = tostring(newContent or "")
				self.Content = bodyText
				contentLbl.Text = bodyText
				recalcHeight()
			end
			function obj:SetDesc(newContent)
				self:SetContent(newContent)
			end
			function obj:Set(newTitle, newContent)
				if newContent == nil then
					self:SetContent(newTitle)
				else
					self:SetTitle(newTitle)
					self:SetContent(newContent)
				end
			end
			function obj:Update(patch)
				if type(patch) == "table" then
					if patch.Title ~= nil then
						self:SetTitle(patch.Title)
					end
					if patch.Content ~= nil or patch.Desc ~= nil then
						self:SetContent(patch.Content or patch.Desc)
					end
				elseif type(patch) == "string" then
					self:SetContent(patch)
				end
			end
			function obj:GetTitle()
				return self.Title
			end
			function obj:GetContent()
				return self.Content
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

