			local lockOverlay, lockBadge = makeLockOverlay(card)
			local isLocked = false

			local obj = {
				Value = initDefault,
				Frame = card,
			}

			local function apply(state, instant, shouldSave, fireCallback)
				state = (state == true)
				obj.Value = state

				local targetBg = state and Theme.Accent or Theme.BgInput
				local targetKnobPos = state and UDim2.new(1, -19, 0.5, 0) or UDim2.new(0, 3, 0.5, 0)
				local targetKnobColor = state and Color3.fromRGB(255, 255, 255) or Theme.TextSecondary
				local targetStroke = state and Theme.BorderAccent or Theme.Border

				if instant then
					switchBg.BackgroundColor3 = targetBg
					knob.Position = targetKnobPos
					knob.BackgroundColor3 = targetKnobColor
					switchStroke.Color = targetStroke
					cardStroke.Color = targetStroke
				else
					tween(switchBg, 0.14, { BackgroundColor3 = targetBg })
					tween(knob, 0.14, { Position = targetKnobPos, BackgroundColor3 = targetKnobColor })
					switchStroke.Color = targetStroke
					cardStroke.Color = targetStroke
				end

				if shouldSave then
					Config.data[configKey] = state
					Config:scheduleSave()
				end
				if fireCallback ~= false then
					safeCallback(cb, state)
				end
			end

			local _, prefVal = Config:register(
				configKey,
				initDefault,
				function(loadedVal)
					apply(loadedVal == true, true, false, true)
				end,
				function()
					return obj.Value
				end,
				function(resetVal)
					apply(resetVal == true, true, false, true)
				end
			)

			-- Exact match with vnhub.delta.luau line 6478: apply(default, true, false, true)
			apply(prefVal == true, true, false, true)

			connectClick(hitBtn, function()
				if isLocked then return end
				apply(not obj.Value, false, true, true)
			end)

			function obj:Set(val, instant)
				if isLocked then return end
				apply(val == true, instant == true, true, true)
			end
			function obj:SetValue(val, instant)
				self:Set(val, instant)
			end
			function obj:GetValue()
				return self.Value
			end
			function obj:LoadValue(val)
				apply(val == true, true, false, true)
			end
			function obj:ResetValue()
				apply(initDefault, true, false, true)
			end
			function obj:SetTitle(t)
				titleLbl.Text = tostring(t or "")
			end
			function obj:SetDesc(d)
				local s = tostring(d or "")
				descLbl.Text = s
				descLbl.Visible = s ~= ""
			end
			function obj:Lock(reason)
				isLocked = true
				lockBadge.Text = "🔒 " .. tostring(reason or "LOCKED")
				lockOverlay.Visible = true
			end
			function obj:Unlock()
				isLocked = false
				lockOverlay.Visible = false
			end
			function obj:IsLocked()
				return isLocked
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

		-- ====================================================================
		-- 4. AddSlider (Exact VNHUB signature: Set(val, nocallback, force))
		-- ====================================================================
		function containerObj:AddSlider(sCfg)
			sCfg = type(sCfg) == "table" and sCfg or {}
			local titleText = tostring(sCfg.Title or "Slider")
			local descText = tostring(sCfg.Content or sCfg.Desc or sCfg.Description or "")
			local minVal = tonumber(sCfg.Min) or 0
			local maxVal = tonumber(sCfg.Max) or 100
			if maxVal <= minVal then
				maxVal = minVal + 1
			end
			local increment = tonumber(sCfg.Increment or sCfg.Rounding or sCfg.Step) or 1
			if increment <= 0 then
				increment = 1
			end
			local initDefault = tonumber(sCfg.Default or sCfg.Value) or minVal
			local cb = sCfg.Callback
			local flag = sanitizeKey(sCfg.Flag or (sectionPrefix .. "_" .. titleText))
			local configKey = "Slider_" .. flag

			local function roundVal(v)
				v = tonumber(v) or minVal
				v = math.clamp(v, minVal, maxVal)
				local snapped = minVal + math.floor(((v - minVal) / increment) + 0.5) * increment
				snapped = math.clamp(snapped, minVal, maxVal)
				if increment >= 1 and math.floor(increment) == increment then
					return math.floor(snapped + 0.5)
				end
				return tonumber(string.format("%.4f", snapped)) or snapped
			end

