				maxVal = tonumber(newMax) or maxVal
				self.Max = maxVal
				apply(self.Value, false, false)
			end
			function obj:SetTitle(t)
				titleLbl.Text = tostring(t or "")
			end
			function obj:SetDesc(d)
				local s = tostring(d or "")
				descLbl.Text = s
				descLbl.Visible = s ~= ""
			end
			function obj:Lock(reason)
				isLocked = true
				lockBadge.Text = "🔒 " .. tostring(reason or "LOCKED")
				lockOverlay.Visible = true
			end
			function obj:Unlock()
				isLocked = false
				lockOverlay.Visible = false
			end
			function obj:IsLocked()
				return isLocked
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

		-- ====================================================================
		-- 5. AddInput (Exact VNHUB live typing + FocusLost + Set(val))
		-- ====================================================================
		function containerObj:AddInput(iCfg)
			iCfg = type(iCfg) == "table" and iCfg or {}
			local titleText = tostring(iCfg.Title or "Input")
			local descText = tostring(iCfg.Content or iCfg.Desc or iCfg.Description or "")
			local initDefault = tostring(iCfg.Default or iCfg.Value or "")
			local placeholder = tostring(iCfg.Placeholder or "Enter value...")
			local isNumeric = (iCfg.Numeric == true or iCfg.NumbersOnly == true)
			local clearOnFocus = (iCfg.ClearTextOnFocus == true)
			local cb = iCfg.Callback
			local flag = sanitizeKey(iCfg.Flag or (sectionPrefix .. "_" .. titleText))
			local configKey = "Input_" .. flag

			local function sanitizeText(val)
				local s = tostring(val or "")
				if isNumeric then
					s = s:gsub("[^0-9%.%-]", "")
				end
				return s
			end

			initDefault = sanitizeText(initDefault)

			local rowH = descText ~= "" and 72 or 58
			local card = create("Frame", {
				Name = "Input_" .. flag,
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, rowH),
				BackgroundColor3 = Theme.BgCard,
				Parent = itemHolder,
			})
			addCorner(card, 8)
			addStroke(card, Theme.Border, 1, 0.3)

			local titleLbl = create("TextLabel", {
				Position = UDim2.new(0, 12, 0, 7),
				Size = UDim2.new(1, -24, 0, 17),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = titleText,
				TextColor3 = Theme.TextPrimary,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = card,
			})

			local descLbl = create("TextLabel", {
				Position = UDim2.new(0, 12, 0, 24),
				Size = UDim2.new(1, -24, 0, 14),
				BackgroundTransparency = 1,
				Font = Theme.FontReg,
				Text = descText,
				TextColor3 = Theme.TextSecondary,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Visible = descText ~= "",
				Parent = card,
			})

			local box = create("TextBox", {
				Position = UDim2.new(0, 12, 1, -30),
				Size = UDim2.new(1, -24, 0, 24),
				BackgroundColor3 = Theme.BgInput,
				Font = Theme.FontReg,
				Text = initDefault,
				PlaceholderText = placeholder,
				PlaceholderColor3 = Theme.TextMuted,
				TextColor3 = Theme.TextPrimary,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
				ClearTextOnFocus = clearOnFocus,
				ZIndex = 6,
				Parent = card,
			}, {
				addPadding(nil, 0, 0, 8, 8),
			})
			addCorner(box, 6)
			local boxStroke = addStroke(box, Theme.Border, 1, 0.25)

			local lockOverlay, lockBadge = makeLockOverlay(card)
			local isLocked = false

			local obj = {
				Value = initDefault,
				Frame = card,
			}

			local suppressTextSignal = false
			local typingToken = 0

			local function apply(val, shouldSave, fireCallback)
				local clean = sanitizeText(val)
				obj.Value = clean
				suppressTextSignal = true
				box.Text = clean
				suppressTextSignal = false

				if shouldSave then
					Config.data[configKey] = clean
					Config:scheduleSave()
				end
				if fireCallback ~= false then
					safeCallback(cb, clean)
				end
			end

			local _, prefVal = Config:register(
				configKey,
				initDefault,
				function(loadedVal)
					apply(loadedVal, false, true)
				end,
				function()
					return obj.Value
				end,
				function(resetVal)
					apply(resetVal, false, true)
				end
			)

			-- Exact match with vnhub.delta.luau line 6937: applyinput(default, false, true)
			apply(prefVal, false, true)

			box.Focused:Connect(function()
				boxStroke.Color = Theme.Accent
			end)

			box:GetPropertyChangedSignal("Text"):Connect(function()
				if suppressTextSignal or isLocked then
					return
				end
				local clean = sanitizeText(box.Text)
				if clean ~= box.Text then
					suppressTextSignal = true
					box.Text = clean
					suppressTextSignal = false
				end
				obj.Value = clean
				Config.data[configKey] = clean
				Config:scheduleSave()
				typingToken = typingToken + 1
				local myToken = typingToken
				task.delay(0.35, function()
					if myToken == typingToken and box:IsFocused() then
						safeCallback(cb, obj.Value)
					end
				end)
			end)

			box.FocusLost:Connect(function()
				boxStroke.Color = Theme.Border
				if isLocked then return end
				typingToken = typingToken + 1
				apply(box.Text, true, true)
			end)

			function obj:Set(val)
				if isLocked then return end
				apply(val, true, true)
			end
			function obj:SetValue(val)
				self:Set(val)
			end
			function obj:GetValue()
				return self.Value
			end
			function obj:LoadValue(val)
				apply(val, false, true)
			end
			function obj:ResetValue()
				apply(initDefault, false, true)
			end
			function obj:SetPlaceholder(p)
				box.PlaceholderText = tostring(p or "")
			end
			function obj:SetTitle(t)
				titleLbl.Text = tostring(t or "")
			end
			function obj:SetDesc(d)
				local s = tostring(d or "")
				descLbl.Text = s
				descLbl.Visible = s ~= ""
			end
			function obj:Lock(reason)
				isLocked = true
				box.TextEditable = false
				lockBadge.Text = "🔒 " .. tostring(reason or "LOCKED")
				lockOverlay.Visible = true
			end
			function obj:Unlock()
				isLocked = false
				box.TextEditable = true
				lockOverlay.Visible = false
			end
			function obj:IsLocked()
				return isLocked
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

		-- ====================================================================
		-- 6. AddDropdown (Exact VNHUB normalize, fire, Set, Refresh(newlist, keep))
		-- ====================================================================
		function containerObj:AddDropdown(dCfg)
			dCfg = type(dCfg) == "table" and dCfg or {}
			local titleText = tostring(dCfg.Title or "Dropdown")
			local descText = tostring(dCfg.Content or dCfg.Desc or dCfg.Description or "")
			local isMulti = (dCfg.Multi == true)
			local rawOptions = type(dCfg.Options or dCfg.Values) == "table" and (dCfg.Options or dCfg.Values) or {}
			local rawDefault = dCfg.Default
			if rawDefault == nil then
				rawDefault = dCfg.Value
			end
			local cb = dCfg.Callback
			local flag = sanitizeKey(dCfg.Flag or (sectionPrefix .. "_" .. titleText))
			local configKey = "Dropdown_" .. flag

			local optionEntries = {}
			local optionByValue = {}

			local function parseOption(raw, idx)
				if type(raw) == "table" then
					local val = tostring(raw.Value or raw.Id or raw.Name or raw.Title or idx)
					local label = tostring(raw.Title or raw.Text or raw.Label or raw.Name or val)
					local desc = tostring(raw.Desc or raw.Description or "")
					local meta = tostring(raw.Meta or raw.Sub or "")
					return {
						Value = val,
						Label = label,
						Desc = desc,
						Meta = meta,
						Raw = raw,
					}
				else
					local val = tostring(raw)
					return {
						Value = val,
						Label = val,
						Desc = "",
						Meta = "",
						Raw = raw,
					}
				end
			end

			local function rebuildOptionTables(list)
				optionEntries = {}
				optionByValue = {}
				if type(list) == "table" then
					for idx, item in ipairs(list) do
						local parsed = parseOption(item, idx)
						table.insert(optionEntries, parsed)
						optionByValue[parsed.Value] = parsed
					end
				end
			end

			rebuildOptionTables(rawOptions)

			local function normalize(value)
				if isMulti then
					local selected = {}
					local seen = {}
					if type(value) == "table" then
						if #value > 0 then
							for _, item in ipairs(value) do
								local k = tostring(item)
								if not seen[k] and (#optionEntries == 0 or optionByValue[k] ~= nil) then
									seen[k] = true
									table.insert(selected, k)
								end
							end
						else
							for k, enabled in pairs(value) do
								local keyStr = tostring(k)
								if enabled and not seen[keyStr] and (#optionEntries == 0 or optionByValue[keyStr] ~= nil) then
									seen[keyStr] = true
									table.insert(selected, keyStr)
								end
							end
						end
					elseif type(value) == "string" and value ~= "" then
						if #optionEntries == 0 or optionByValue[value] ~= nil then
							table.insert(selected, value)
						end
					end
					return selected
				else
					if type(value) == "table" then
						value = value[1]
					end
					if value == nil or value == "" then
						return nil
					end
					local str = tostring(value)
					if #optionEntries > 0 and optionByValue[str] == nil then
						return str
					end
					return str
				end
			end

			local initDefault = normalize(rawDefault)

			local headerH = descText ~= "" and 52 or 40
			local card = create("Frame", {
				Name = "Dropdown_" .. flag,
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, headerH),
				BackgroundColor3 = Theme.BgCard,
				ClipsDescendants = true,
				Parent = itemHolder,
			})
			addCorner(card, 8)
			local cardStroke = addStroke(card, Theme.Border, 1, 0.3)

			local headerFrame = create("Frame", {
				Size = UDim2.new(1, 0, 0, headerH),
				BackgroundTransparency = 1,
				Parent = card,
			})

			local titleLbl = create("TextLabel", {
				Position = UDim2.new(0, 12, 0, descText ~= "" and 7 or 11),
				Size = UDim2.new(0.52, -16, 0, 18),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = titleText,
				TextColor3 = Theme.TextPrimary,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = headerFrame,
			})

			local descLbl = create("TextLabel", {
				Position = UDim2.new(0, 12, 0, 26),
				Size = UDim2.new(0.52, -16, 0, 16),
				BackgroundTransparency = 1,
				Font = Theme.FontReg,
				Text = descText,
				TextColor3 = Theme.TextSecondary,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Visible = descText ~= "",
				Parent = headerFrame,
			})

			local valuePill = create("Frame", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -10, 0.5, 0),
				Size = UDim2.new(0.46, -6, 0, 26),
				BackgroundColor3 = Theme.BgInput,
				Parent = headerFrame,
			})
			addCorner(valuePill, 6)
			addStroke(valuePill, Theme.Border, 1, 0.25)

			local selectedLbl = create("TextLabel", {
				Position = UDim2.new(0, 8, 0, 0),
				Size = UDim2.new(1, -26, 1, 0),
				BackgroundTransparency = 1,
				Font = Theme.FontSemi,
				Text = "None",
				TextColor3 = Theme.Accent,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = valuePill,
			})

			local arrowLbl = create("TextLabel", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -6, 0.5, 0),
				Size = UDim2.new(0, 14, 0, 14),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = "▾",
				TextColor3 = Theme.TextSecondary,
				TextSize = 12,
				Parent = valuePill,
			})

			local headerHit = create("TextButton", {
				Size = UDim2.new(1, 0, 1, 0),
				BackgroundTransparency = 1,
				Text = "",
				ZIndex = 6,
				Parent = headerFrame,
			})

			-- Expandable Panel
			local dropPanel = create("Frame", {
				Position = UDim2.new(0, 8, 0, headerH),
				Size = UDim2.new(1, -16, 0, 170),
				BackgroundColor3 = Theme.BgSecondary,
				Visible = false,
				Parent = card,
			})
			addCorner(dropPanel, 7)
			addStroke(dropPanel, Theme.Border, 1, 0.3)

			local searchBox = create("TextBox", {
				Position = UDim2.new(0, 6, 0, 6),
				Size = UDim2.new(1, -12, 0, 24),
				BackgroundColor3 = Theme.BgInput,
				Font = Theme.FontReg,
				Text = "",
				PlaceholderText = "Search options...",
				PlaceholderColor3 = Theme.TextMuted,
				TextColor3 = Theme.TextPrimary,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				ClearTextOnFocus = false,
				ZIndex = 7,
				Parent = dropPanel,
			}, {
				addPadding(nil, 0, 0, 8, 8),
			})
			addCorner(searchBox, 5)
			addStroke(searchBox, Theme.Border, 1, 0.3)

			local optScroll = create("ScrollingFrame", {
				Position = UDim2.new(0, 6, 0, 34),
				Size = UDim2.new(1, -12, 1, -40),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ScrollBarThickness = 3,
				ScrollBarImageColor3 = Theme.Accent,
				CanvasSize = UDim2.new(0, 0, 0, 0),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				ZIndex = 7,
				Parent = dropPanel,
			}, {
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 4),
				}),
			})

			local lockOverlay, lockBadge = makeLockOverlay(card)
			local isLocked = false
			local isOpen = false

			local obj = {
				Value = cloneValue(initDefault),
				Options = rawOptions,
				Multi = isMulti,
				Frame = card,
			}

			local function isValueSelected(valStr)
				if isMulti then
					if type(obj.Value) == "table" then
						for _, item in ipairs(obj.Value) do
							if tostring(item) == valStr then
								return true
							end
						end
					end
					return false
				else
					return obj.Value ~= nil and tostring(obj.Value) == valStr
				end
			end

			local function updateSummaryText()
				if isMulti then
					local list = type(obj.Value) == "table" and obj.Value or {}
					if #list == 0 then
						selectedLbl.Text = "None"
						selectedLbl.TextColor3 = Theme.TextMuted
					elseif #list <= 2 then
						local labels = {}
						for _, v in ipairs(list) do
							local entry = optionByValue[tostring(v)]
							table.insert(labels, entry and entry.Label or tostring(v))
						end
						selectedLbl.Text = table.concat(labels, ", ")
						selectedLbl.TextColor3 = Theme.Accent
					else
						selectedLbl.Text = tostring(#list) .. " Selected"
						selectedLbl.TextColor3 = Theme.Accent
					end
				else
					if obj.Value == nil or obj.Value == "" then
						selectedLbl.Text = "None"
						selectedLbl.TextColor3 = Theme.TextMuted
					else
						local entry = optionByValue[tostring(obj.Value)]
						selectedLbl.Text = entry and entry.Label or tostring(obj.Value)
						selectedLbl.TextColor3 = Theme.Accent
					end
				end
			end

			local function fire()
				if isMulti then
					safeCallback(cb, copyArray(obj.Value))
				else
					safeCallback(cb, obj.Value ~= nil and tostring(obj.Value) or "")
				end
			end

			local optionButtons = {}

			local function refreshOptionVisuals()
				local query = tostring(searchBox.Text or ""):lower()
				local visibleCount = 0
				for _, item in ipairs(optionButtons) do
					local match = (query == "")
						or item.Entry.Label:lower():find(query, 1, true) ~= nil
						or item.Entry.Value:lower():find(query, 1, true) ~= nil
					item.Button.Visible = match
					if match then
						visibleCount = visibleCount + 1
					end
					local sel = isValueSelected(item.Entry.Value)
					item.Button.BackgroundColor3 = sel and Theme.BgCardHover or Theme.BgCard
					item.Title.TextColor3 = sel and Theme.Accent or Theme.TextPrimary
					item.Check.Text = sel and "✓" or ""
					item.Stroke.Color = sel and Theme.BorderAccent or Theme.Border
					item.Stroke.Transparency = sel and 0.2 or 0.5
				end
				local panelH = math.clamp(38 + math.max(1, math.min(visibleCount, 5)) * 30, 74, 190)
				dropPanel.Size = UDim2.new(1, -16, 0, panelH)
				if isOpen then
					card.Size = UDim2.new(1, 0, 0, headerH + panelH + 8)
				else
					card.Size = UDim2.new(1, 0, 0, headerH)
				end
			end

			local apply

			local function buildOptionButtons()
				for _, child in ipairs(optScroll:GetChildren()) do
					if not child:IsA("UIListLayout") then
						child:Destroy()
					end
				end
				optionButtons = {}

				for idx, entry in ipairs(optionEntries) do
					local hasSub = (entry.Desc ~= "" or entry.Meta ~= "")
					local btnH = hasSub and 38 or 28
					local optBtn = create("TextButton", {
						LayoutOrder = idx,
						Size = UDim2.new(1, -4, 0, btnH),
						BackgroundColor3 = Theme.BgCard,
						Text = "",
						AutoButtonColor = false,
						ZIndex = 8,
						Parent = optScroll,
					})
					addCorner(optBtn, 6)
					local optStroke = addStroke(optBtn, Theme.Border, 1, 0.5)

					local optTitle = create("TextLabel", {
						Position = UDim2.new(0, 10, 0, hasSub and 3 or 5),
						Size = UDim2.new(1, -34, 0, 16),
						BackgroundTransparency = 1,
						Font = Theme.FontSemi,
						Text = entry.Label,
						TextColor3 = Theme.TextPrimary,
						TextSize = 12,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						ZIndex = 9,
						Parent = optBtn,
					})

					if hasSub then
						local subStr = entry.Desc ~= "" and entry.Desc or entry.Meta
						create("TextLabel", {
							Position = UDim2.new(0, 10, 0, 19),
							Size = UDim2.new(1, -34, 0, 14),
							BackgroundTransparency = 1,
							Font = Theme.FontReg,
							Text = subStr,
							TextColor3 = Theme.TextSecondary,
							TextSize = 10,
							TextXAlignment = Enum.TextXAlignment.Left,
							TextTruncate = Enum.TextTruncate.AtEnd,
							ZIndex = 9,
							Parent = optBtn,
						})
					end

					local checkLbl = create("TextLabel", {
						AnchorPoint = Vector2.new(1, 0.5),
						Position = UDim2.new(1, -8, 0.5, 0),
						Size = UDim2.new(0, 18, 0, 18),
						BackgroundTransparency = 1,
						Font = Theme.FontBold,
						Text = "",
						TextColor3 = Theme.Accent,
						TextSize = 13,
						ZIndex = 9,
						Parent = optBtn,
					})

					connectClick(optBtn, function()
						if isLocked then return end
						if isMulti then
							local cur = type(obj.Value) == "table" and copyArray(obj.Value) or {}
							local foundIdx = nil
							for i, v in ipairs(cur) do
								if tostring(v) == entry.Value then
									foundIdx = i
									break
								end
							end
							if foundIdx then
								table.remove(cur, foundIdx)
							else
								table.insert(cur, entry.Value)
							end
							apply(cur, false, true, true)
						else
							apply(entry.Value, false, true, true)
							isOpen = false
							dropPanel.Visible = false
							arrowLbl.Text = "▾"
							cardStroke.Color = Theme.Border
							refreshOptionVisuals()
						end
					end)

					table.insert(optionButtons, {
						Entry = entry,
						Button = optBtn,
						Title = optTitle,
						Check = checkLbl,
						Stroke = optStroke,
					})
				end
				refreshOptionVisuals()
			end

			apply = function(val, instant, shouldSave, fireCallback)
				obj.Value = normalize(val)
				updateSummaryText()
				refreshOptionVisuals()

				if shouldSave then
					Config.data[configKey] = cloneValue(obj.Value)
					Config:scheduleSave()
				end
				if fireCallback ~= false then
					fire()
				end
			end

			buildOptionButtons()

			local _, prefVal = Config:register(
				configKey,
				initDefault,
				function(loadedVal)
					apply(loadedVal, true, false, true)
				end,
				function()
					return cloneValue(obj.Value)
				end,
				function(resetVal)
					apply(resetVal, true, false, true)
				end
			)

			-- Exact match with vnhub.delta.luau line 7438: apply(default, true, false, true)
			apply(prefVal, true, false, true)

			searchBox:GetPropertyChangedSignal("Text"):Connect(function()
				refreshOptionVisuals()
			end)

			connectClick(headerHit, function()
				if isLocked then return end
				isOpen = not isOpen
				dropPanel.Visible = isOpen
				arrowLbl.Text = isOpen and "▴" or "▾"
				cardStroke.Color = isOpen and Theme.BorderAccent or Theme.Border
				refreshOptionVisuals()
			end)

			function obj:Set(val, instant, force)
				if isLocked and not force then return end
				apply(val, instant == true, not isLocked, true)
			end
			function obj:SetValue(val, instant, force)
				self:Set(val, instant, force)
			end
			function obj:GetValue()
				return self.Value
			end
			function obj:LoadValue(val)
				apply(val, true, false, true)
			end
			function obj:ResetValue()
				apply(initDefault, true, false, true)
			end
			function obj:Refresh(newList, keep)
				rawOptions = type(newList) == "table" and newList or {}
				self.Options = rawOptions
				rebuildOptionTables(rawOptions)
				buildOptionButtons()
				local nextVal = (keep == false) and (isMulti and {} or nil) or self.Value
				apply(nextVal, true, not isLocked, false)
			end
			function obj:SetValues(newList, keep)
				self:Refresh(newList, keep)
			end
			function obj:SetOptions(newList, keep)
				self:Refresh(newList, keep)
			end
			function obj:GetOptions()
				return rawOptions
			end
			function obj:Clear()
				self:Set(isMulti and {} or nil, false, true)
			end
			function obj:SetTitle(t)
				titleLbl.Text = tostring(t or "")
			end
			function obj:SetDesc(d)
				local s = tostring(d or "")
				descLbl.Text = s
				descLbl.Visible = s ~= ""
			end
			function obj:Lock(reason)
				isLocked = true
				isOpen = false
				dropPanel.Visible = false
				card.Size = UDim2.new(1, 0, 0, headerH)
				lockBadge.Text = "🔒 " .. tostring(reason or "LOCKED")
				lockOverlay.Visible = true
			end
			function obj:Unlock()
				isLocked = false
				lockOverlay.Visible = false
			end
			function obj:IsLocked()
				return isLocked
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

		-- ====================================================================
		-- 7. AddIconGrid (Catalog / Brainrot / Butterfly Grid)
		-- ====================================================================
		function containerObj:AddIconGrid(gCfg)
			gCfg = type(gCfg) == "table" and gCfg or {}
			local titleText = tostring(gCfg.Title or "")
			local noteText = tostring(gCfg.Note or "")
			local emptyText = tostring(gCfg.EmptyText or "No items matching current filter.")
			local cols = math.max(1, tonumber(gCfg.Columns) or 4)
			local maxH = tonumber(gCfg.MaxHeight) or 260
			local cardH = tonumber(gCfg.CardHeight) or 106
			local topOffset = (titleText ~= "" or noteText ~= "") and 28 or 6

			local wrapper = create("Frame", {
				Name = "IconGrid",
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, topOffset + 46),
				BackgroundColor3 = Theme.BgCard,
				Parent = itemHolder,
			})
			addCorner(wrapper, 8)
			addStroke(wrapper, Theme.Border, 1, 0.3)

			local headerTitle = create("TextLabel", {
				Position = UDim2.new(0, 10, 0, 6),
				Size = UDim2.new(0.55, -10, 0, 18),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = titleText,
				TextColor3 = Theme.TextPrimary,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
				Visible = titleText ~= "",
				Parent = wrapper,
			})

			local noteLbl = create("TextLabel", {
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -10, 0, 6),
				Size = UDim2.new(0.45, -10, 0, 18),
				BackgroundTransparency = 1,
				Font = Theme.FontSemi,
				Text = noteText,
				TextColor3 = Theme.Accent,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Right,
				Visible = noteText ~= "",
				Parent = wrapper,
			})

			local emptyLbl = create("TextLabel", {
				Size = UDim2.new(1, -20, 0, 40),
				Position = UDim2.new(0, 10, 0, topOffset),
				BackgroundTransparency = 1,
				Font = Theme.FontReg,
				Text = emptyText,
				TextColor3 = Theme.TextMuted,
				TextSize = 12,
				TextWrapped = true,
				Parent = wrapper,
			})

			local gridScroll = create("ScrollingFrame", {
				Position = UDim2.new(0, 6, 0, topOffset),
				Size = UDim2.new(1, -12, 1, -(topOffset + 6)),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ScrollBarThickness = 3,
				ScrollBarImageColor3 = Theme.Accent,
				CanvasSize = UDim2.new(0, 0, 0, 0),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				Visible = false,
				Parent = wrapper,
			})

			local cellW = math.floor(1 / cols * 1000) / 1000
			create("UIGridLayout", {
				CellSize = UDim2.new(cellW, -6, 0, cardH),
				CellPadding = UDim2.new(0, 6, 0, 6),
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = gridScroll,
			})

			local obj = { Frame = wrapper }

			function obj:Refresh(items)
				items = type(items) == "table" and items or {}
				for _, child in ipairs(gridScroll:GetChildren()) do
					if not child:IsA("UIGridLayout") then
						child:Destroy()
					end
				end
				if #items == 0 then
					emptyLbl.Visible = true
					gridScroll.Visible = false
					wrapper.Size = UDim2.new(1, 0, 0, topOffset + 46)
					return
				end

				emptyLbl.Visible = false
				gridScroll.Visible = true
				local rows = math.ceil(#items / cols)
				local desiredH = math.clamp(topOffset + rows * (cardH + 6) + 8, topOffset + cardH + 10, maxH)
				wrapper.Size = UDim2.new(1, 0, 0, desiredH)

				for idx, item in ipairs(items) do
					local isSel = item.Selected == true
					local itemColor = item.Color or (isSel and Theme.Accent or Theme.Border)
					local cell = create("TextButton", {
						LayoutOrder = idx,
						BackgroundColor3 = isSel and Theme.BgCardHover or Theme.BgSecondary,
						Text = "",
						AutoButtonColor = false,
						Parent = gridScroll,
					})
					addCorner(cell, 7)
					addStroke(cell, itemColor, 1, isSel and 0.15 or 0.45)

					if item.Icon and tostring(item.Icon) ~= "" then
						create("ImageLabel", {
							AnchorPoint = Vector2.new(0.5, 0),
							Position = UDim2.new(0.5, 0, 0, 6),
							Size = UDim2.new(0, 40, 0, 40),
							BackgroundTransparency = 1,
							Image = resolveAsset(tostring(item.Icon), Icons.info),
							ScaleType = Enum.ScaleType.Fit,
							Parent = cell,
						})
					end

					create("TextLabel", {
						Position = UDim2.new(0, 4, 1, -44),
						Size = UDim2.new(1, -8, 0, 16),
						BackgroundTransparency = 1,
						Font = Theme.FontBold,
						Text = tostring(item.Title or item.Name or item.name or ("Item " .. idx)),
						TextColor3 = item.Color or (isSel and Theme.Accent or Theme.TextPrimary),
						TextSize = 11,
						RichText = true,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = cell,
					})

					create("TextLabel", {
						Position = UDim2.new(0, 4, 1, -28),
						Size = UDim2.new(1, -8, 0, 13),
						BackgroundTransparency = 1,
						Font = Theme.FontSemi,
						Text = tostring(item.Value or item.Meta or item.Rarity or ""),
						TextColor3 = Theme.Warning,
						TextSize = 10,
						RichText = true,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = cell,
					})

					create("TextLabel", {
						Position = UDim2.new(0, 4, 1, -15),
						Size = UDim2.new(1, -8, 0, 12),
						BackgroundTransparency = 1,
						Font = Theme.FontReg,
						Text = tostring(item.Sub or item.SubMeta or ""),
						TextColor3 = item.SubColor or Theme.TextSecondary,
						TextSize = 9,
						RichText = true,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = cell,
					})

					connectClick(cell, function()
						if type(item.Callback) == "function" then
							safeCallback(item.Callback, item)
						elseif type(gCfg.Callback) == "function" then
							safeCallback(gCfg.Callback, item)
						end
					end)
				end
			end

			function obj:SetItems(items)
				self:Refresh(items)
			end
			function obj:Update(items)
				self:Refresh(items)
			end
			function obj:SetNote(text)
				noteText = tostring(text or "")
				noteLbl.Text = noteText
				noteLbl.Visible = noteText ~= ""
			end
			function obj:SetTitle(text)
				titleText = tostring(text or "")
				headerTitle.Text = titleText
				headerTitle.Visible = titleText ~= ""
			end
			function obj:SetEmptyText(t)
				emptyText = tostring(t or "")
				emptyLbl.Text = emptyText
			end
			function obj:SetVisible(vis)
				wrapper.Visible = vis == true
			end
			function obj:Alive()
				return wrapper ~= nil and wrapper.Parent ~= nil
			end
			function obj:Destroy()
				if wrapper and wrapper.Parent then
					wrapper:Destroy()
				end
			end

			obj:Refresh(gCfg.Items or {})
			return obj
		end

		-- ====================================================================
		-- 8. AddActionList (Placed Eggs / Player Steal / History Action List)
		-- ====================================================================
		function containerObj:AddActionList(aCfg)
			aCfg = type(aCfg) == "table" and aCfg or {}
			local titleText = tostring(aCfg.Title or "")
			local emptyText = tostring(aCfg.EmptyText or "Nothing selected.")
			local visRows = tonumber(aCfg.VisibleRows) or 5
			local rowH = tonumber(aCfg.RowHeight) or 46
			local btnW = tonumber(aCfg.ButtonWidth) or 68
			local maxH = tonumber(aCfg.MaxHeight) or (visRows * (rowH + 5) + 38)
			local topOffset = titleText ~= "" and 26 or 6

			local wrapper = create("Frame", {
				Name = "ActionList",
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, topOffset + 42),
				BackgroundColor3 = Theme.BgCard,
				Parent = itemHolder,
			})
			addCorner(wrapper, 8)
			addStroke(wrapper, Theme.Border, 1, 0.3)

			if titleText ~= "" then
				create("TextLabel", {
					Position = UDim2.new(0, 10, 0, 5),
					Size = UDim2.new(1, -20, 0, 18),
					BackgroundTransparency = 1,
					Font = Theme.FontBold,
					Text = titleText,
					TextColor3 = Theme.TextPrimary,
					TextSize = 12,
					TextXAlignment = Enum.TextXAlignment.Left,
					Parent = wrapper,
				})
			end

			local emptyLbl = create("TextLabel", {
				Size = UDim2.new(1, -20, 0, 36),
				Position = UDim2.new(0, 10, 0, topOffset),
				BackgroundTransparency = 1,
				Font = Theme.FontReg,
				Text = emptyText,
				TextColor3 = Theme.TextMuted,
				TextSize = 12,
				TextWrapped = true,
				Parent = wrapper,
			})

			local listScroll = create("ScrollingFrame", {
				Position = UDim2.new(0, 6, 0, topOffset),
				Size = UDim2.new(1, -12, 1, -(topOffset + 6)),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ScrollBarThickness = 3,
				ScrollBarImageColor3 = Theme.Accent,
				CanvasSize = UDim2.new(0, 0, 0, 0),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				Visible = false,
				Parent = wrapper,
			}, {
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 5),
				}),
			})

			local obj = { Frame = wrapper }

			local function resolveBtnColor(tone)
				if tone == "green" then
					return Theme.Success
				elseif tone == "red" then
					return Theme.Danger
				elseif tone == "warn" or tone == "yellow" then
					return Theme.Warning
				elseif tone == "accent" then
					return Theme.AccentDark
				end
				return Theme.AccentDark
			end

			function obj:Refresh(items)
				items = type(items) == "table" and items or {}
				for _, child in ipairs(listScroll:GetChildren()) do
					if not child:IsA("UIListLayout") then
						child:Destroy()
					end
				end
				if #items == 0 then
					emptyLbl.Visible = true
					listScroll.Visible = false
					wrapper.Size = UDim2.new(1, 0, 0, topOffset + 42)
					return
				end

				emptyLbl.Visible = false
				listScroll.Visible = true
				local desiredH = math.clamp(topOffset + #items * (rowH + 5) + 8, topOffset + rowH + 8, maxH)
				wrapper.Size = UDim2.new(1, 0, 0, desiredH)

				for idx, item in ipairs(items) do
					local row = create("Frame", {
						LayoutOrder = idx,
						Size = UDim2.new(1, -4, 0, rowH),
						BackgroundColor3 = Theme.BgSecondary,
						Parent = listScroll,
					})
					addCorner(row, 6)
					addStroke(row, Theme.Border, 1, 0.4)

					local hasButton = (item.button ~= false) and (item.button ~= nil or item.ActionText ~= nil or item.onClick ~= nil or item.Callback ~= nil)
					local rightReserve = hasButton and (btnW + 18) or 10

					local primaryTitle = tostring(item.Title or item.Name or item.name or ("Item " .. idx))
					local primarySub = tostring(item.sub or item.Desc or item.Meta or "")
					local statusTop = tostring(item.status or "")
					local statusBottom = tostring(item.statusSub or "")

					create("TextLabel", {
						Position = UDim2.new(0, 10, 0, 5),
						Size = UDim2.new(0.45, -12, 0, 16),
						BackgroundTransparency = 1,
						Font = Theme.FontBold,
						Text = primaryTitle,
						TextColor3 = Theme.TextPrimary,
						TextSize = 12,
						RichText = true,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = row,
					})

					create("TextLabel", {
						Position = UDim2.new(0, 10, 0, 23),
						Size = UDim2.new(0.45, -12, 0, 14),
						BackgroundTransparency = 1,
						Font = Theme.FontReg,
						Text = primarySub,
						TextColor3 = Theme.TextSecondary,
						TextSize = 10,
						RichText = true,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = row,
					})

					if statusTop ~= "" or statusBottom ~= "" then
						create("TextLabel", {
							Position = UDim2.new(0.45, 4, 0, 5),
							Size = UDim2.new(0.55, -(rightReserve + 4), 0, 16),
							BackgroundTransparency = 1,
							Font = Theme.FontSemi,
							Text = statusTop,
							TextColor3 = Theme.TextPrimary,
							TextSize = 11,
							RichText = true,
							TextXAlignment = Enum.TextXAlignment.Right,
							TextTruncate = Enum.TextTruncate.AtEnd,
							Parent = row,
						})
						create("TextLabel", {
							Position = UDim2.new(0.45, 4, 0, 23),
							Size = UDim2.new(0.55, -(rightReserve + 4), 0, 14),
							BackgroundTransparency = 1,
							Font = Theme.FontReg,
							Text = statusBottom,
							TextColor3 = Theme.TextSecondary,
							TextSize = 10,
							RichText = true,
							TextXAlignment = Enum.TextXAlignment.Right,
							TextTruncate = Enum.TextTruncate.AtEnd,
							Parent = row,
						})
					end

					if hasButton then
						local btnLabel = type(item.button) == "string" and item.button or tostring(item.ActionText or "Action")
						local actBtn = create("TextButton", {
							AnchorPoint = Vector2.new(1, 0.5),
							Position = UDim2.new(1, -8, 0.5, 0),
							Size = UDim2.new(0, btnW, 0, 24),
							BackgroundColor3 = resolveBtnColor(item.buttonColor),
							Font = Theme.FontBold,
							Text = btnLabel,
							TextColor3 = Theme.TextPrimary,
							TextSize = 11,
							AutoButtonColor = false,
							Parent = row,
						})
						addCorner(actBtn, 5)
						local function setBtnState(newText, newTone)
							if actBtn and actBtn.Parent then
								if newText ~= nil then
									actBtn.Text = tostring(newText)
								end
								if newTone ~= nil then
									actBtn.BackgroundColor3 = resolveBtnColor(newTone)
								end
							end
						end
						connectClick(actBtn, function()
							if type(item.onClick) == "function" then
								safeCallback(item.onClick, item, setBtnState)
							elseif type(item.Callback) == "function" then
								safeCallback(item.Callback, item, setBtnState)
							end
						end)
					end
				end
			end

			function obj:Update(items)
				self:Refresh(items)
			end
			function obj:SetItems(items)
				self:Refresh(items)
			end
			function obj:SetEmptyText(t)
				emptyText = tostring(t or "")
				emptyLbl.Text = emptyText
			end
			function obj:SetVisible(vis)
				wrapper.Visible = vis == true
			end
			function obj:Alive()
				return wrapper ~= nil and wrapper.Parent ~= nil
			end
			function obj:Destroy()
				if wrapper and wrapper.Parent then
					wrapper:Destroy()
				end
			end

			obj:Refresh(aCfg.Items or {})
			return obj
		end

		-- ====================================================================
		-- 9. AddPriorityList (Exact VNHUB Task Coordinator Priority Order)
		-- ====================================================================
		function containerObj:AddPriorityList(pCfg)
			pCfg = type(pCfg) == "table" and pCfg or {}
			local titleText = tostring(pCfg.Title or "Task Priority")
			local descText = tostring(pCfg.Content or pCfg.Desc or pCfg.Description or "")
			local items = type(pCfg.Items) == "table" and pCfg.Items or {}
			local cb = pCfg.Callback
			local flag = sanitizeKey(pCfg.Flag or (sectionPrefix .. "_" .. titleText))
			local configKey = "Priority_" .. flag

			local itemMap = {}
			local itemOrder = {}
			local statusMap = {}

			for idx, raw in ipairs(items) do
				local id = tostring(type(raw) == "table" and (raw.Id or raw.Value or raw.Name or raw.Title) or raw or idx)
				local entry = {
					Id = id,
					Title = tostring(type(raw) == "table" and (raw.Title or raw.Name or id) or id),
					Desc = tostring(type(raw) == "table" and (raw.Desc or raw.Description or "") or ""),
					Color = type(raw) == "table" and raw.Color or Theme.Accent,
					Pinned = type(raw) == "table" and raw.Pinned == true or false,
				}
				itemMap[id] = entry
				table.insert(itemOrder, id)
				statusMap[id] = {
					Text = entry.Pinned and "BASE" or "OFF",
					Tone = "off",
				}
			end

			local function sanitizeOrder(order)
				local out = {}
				local seen = {}
				if type(order) == "table" then
					for _, rawId in ipairs(order) do
						local id = tostring(rawId)
						local item = itemMap[id]
						if item and not item.Pinned and not seen[id] then
							seen[id] = true
							table.insert(out, id)
						end
					end
				end
				for _, id in ipairs(itemOrder) do
					local item = itemMap[id]
					if item and not item.Pinned and not seen[id] then
						seen[id] = true
						table.insert(out, id)
					end
				end
				for _, id in ipairs(itemOrder) do
					local item = itemMap[id]
					if item and item.Pinned and not seen[id] then
						seen[id] = true
						table.insert(out, id)
					end
				end
				return out
			end

			local initDefault = sanitizeOrder(pCfg.Default or itemOrder)
			local currentOrder = copyArray(initDefault)

			local headerH = descText ~= "" and 48 or 34
			local totalH = headerH + (#itemOrder * 42) + 10

			local card = create("Frame", {
				Name = "Priority_" .. flag,
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, totalH),
				BackgroundColor3 = Theme.BgCard,
				Parent = itemHolder,
			})
			addCorner(card, 8)
			addStroke(card, Theme.Border, 1, 0.3)

			create("TextLabel", {
				Position = UDim2.new(0, 12, 0, 7),
				Size = UDim2.new(1, -24, 0, 17),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = titleText,
				TextColor3 = Theme.TextPrimary,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				Parent = card,
			})

			if descText ~= "" then
				create("TextLabel", {
					Position = UDim2.new(0, 12, 0, 24),
					Size = UDim2.new(1, -24, 0, 15),
					BackgroundTransparency = 1,
					Font = Theme.FontReg,
					Text = descText,
					TextColor3 = Theme.TextSecondary,
					TextSize = 11,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Parent = card,
				})
			end

			local rowsContainer = create("Frame", {
				Position = UDim2.new(0, 8, 0, headerH),
				Size = UDim2.new(1, -16, 1, -(headerH + 6)),
				BackgroundTransparency = 1,
				Parent = card,
			}, {
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 4),
				}),
			})

			local rows = {}

			local function visibleOrder()
				local out = {}
				for _, id in ipairs(currentOrder) do
					local item = itemMap[id]
					if item and not item.Pinned then
						table.insert(out, id)
					end
				end
				return out
			end

			local obj = {
				Value = copyArray(currentOrder),
				Frame = card,
			}

			local apply

			local function moveItem(id, delta)
				local item = itemMap[id]
				if not item or item.Pinned then
					return
				end
				local order = visibleOrder()
				local idx = table.find(order, id)
				if not idx then
					return
				end
				local targetIdx = math.clamp(idx + delta, 1, #order)
				if targetIdx == idx then
					return
				end
				table.remove(order, idx)
				table.insert(order, targetIdx, id)
				apply(order, false, true, true)
			end

			for _, id in ipairs(itemOrder) do
				local entry = itemMap[id]
				local row = create("Frame", {
					Size = UDim2.new(1, 0, 0, 38),
					BackgroundColor3 = Theme.BgSecondary,
					Parent = rowsContainer,
				})
				addCorner(row, 6)
				addStroke(row, Theme.Border, 1, 0.4)

				local rankBadge = create("TextLabel", {
					AnchorPoint = Vector2.new(0, 0.5),
					Position = UDim2.new(0, 8, 0.5, 0),
					Size = UDim2.new(0, 30, 0, 22),
					BackgroundColor3 = Theme.BgCard,
					Font = Theme.FontBold,
					Text = entry.Pinned and "PIN" or "1",
					TextColor3 = entry.Color or Theme.Accent,
					TextSize = 10,
					Parent = row,
				})
				addCorner(rankBadge, 5)

				create("TextLabel", {
					Position = UDim2.new(0, 44, 0, 4),
					Size = UDim2.new(1, -172, 0, 15),
					BackgroundTransparency = 1,
					Font = Theme.FontBold,
					Text = entry.Title,
					TextColor3 = Theme.TextPrimary,
					TextSize = 12,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Parent = row,
				})

				create("TextLabel", {
					Position = UDim2.new(0, 44, 0, 19),
					Size = UDim2.new(1, -172, 0, 13),
					BackgroundTransparency = 1,
					Font = Theme.FontReg,
					Text = entry.Desc,
					TextColor3 = Theme.TextSecondary,
					TextSize = 10,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Parent = row,
				})

				local statusBadge = create("TextLabel", {
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, -56, 0.5, 0),
					Size = UDim2.new(0, 58, 0, 20),
					BackgroundColor3 = Theme.BgCard,
					Font = Theme.FontBold,
					Text = statusMap[id].Text,
					TextColor3 = Theme.TextMuted,
					TextSize = 10,
					Parent = row,
				})
				addCorner(statusBadge, 5)
				local statusStroke = addStroke(statusBadge, Theme.Border, 1, 0.35)

				local upBtn = create("TextButton", {
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, -30, 0.5, 0),
					Size = UDim2.new(0, 22, 0, 22),
					BackgroundColor3 = Theme.BgCard,
					Font = Theme.FontBold,
					Text = "▲",
					TextColor3 = Theme.TextPrimary,
					TextSize = 10,
					AutoButtonColor = false,
					Visible = not entry.Pinned,
					Parent = row,
				})
				addCorner(upBtn, 5)

				local downBtn = create("TextButton", {
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, -5, 0.5, 0),
					Size = UDim2.new(0, 22, 0, 22),
					BackgroundColor3 = Theme.BgCard,
					Font = Theme.FontBold,
					Text = "▼",
					TextColor3 = Theme.TextPrimary,
					TextSize = 10,
					AutoButtonColor = false,
					Visible = not entry.Pinned,
					Parent = row,
				})
				addCorner(downBtn, 5)

				connectClick(upBtn, function()
					moveItem(id, -1)
				end)
				connectClick(downBtn, function()
					moveItem(id, 1)
				end)

				rows[id] = {
					Row = row,
					Rank = rankBadge,
					Status = statusBadge,
					StatusStroke = statusStroke,
					Up = upBtn,
					Down = downBtn,
				}
			end

			local function refreshVisuals()
				local movable = visibleOrder()
				local movableIndex = {}
				for idx, id in ipairs(movable) do
					movableIndex[id] = idx
				end

				for idx, id in ipairs(currentOrder) do
					local r = rows[id]
					local entry = itemMap[id]
					local state = statusMap[id] or { Text = "OFF", Tone = "off" }
					if r and entry then
						r.Row.LayoutOrder = idx
						r.Rank.Text = entry.Pinned and "PIN" or tostring(movableIndex[id] or idx)
						r.Status.Text = tostring(state.Text or "OFF")

						if state.Tone == "run" then
							r.Status.TextColor3 = Theme.Success
							r.StatusStroke.Color = Theme.Success
						elseif state.Tone == "wait" then
							r.Status.TextColor3 = Theme.Warning
							r.StatusStroke.Color = Theme.Warning
						else
							r.Status.TextColor3 = Theme.TextMuted
							r.StatusStroke.Color = Theme.Border
						end

						if not entry.Pinned then
							local pos = movableIndex[id] or 1
							r.Up.TextTransparency = (pos <= 1) and 0.6 or 0
							r.Down.TextTransparency = (pos >= #movable) and 0.6 or 0
						end
					end
				end
			end

			apply = function(order, instant, shouldSave, fireCallback)
				currentOrder = sanitizeOrder(order)
				obj.Value = copyArray(currentOrder)
				refreshVisuals()

				if shouldSave then
					Config.data[configKey] = copyArray(currentOrder)
					Config:scheduleSave()
				end
				if fireCallback ~= false then
					safeCallback(cb, copyArray(currentOrder))
				end
			end

			local _, prefVal = Config:register(
				configKey,
				initDefault,
				function(loadedVal)
					apply(loadedVal, true, false, true)
				end,
				function()
					return copyArray(currentOrder)
				end,
				function(resetVal)
					apply(resetVal, true, false, true)
				end
			)

