			apply(prefVal, true, false, true)

			function obj:Set(order, instant)
				apply(order, instant == true, true, true)
			end
			function obj:SetValue(order, instant)
				self:Set(order, instant)
			end
			function obj:GetValue()
				return copyArray(currentOrder)
			end
			function obj:LoadValue(order)
				apply(order, true, false, true)
			end
			function obj:ResetValue()
				apply(initDefault, true, false, true)
			end
			function obj:SetStatus(id, text, tone)
				id = tostring(id or "")
				if not rows[id] then
					return
				end
				statusMap[id] = {
					Text = tostring(text or "OFF"),
					Tone = tostring(tone or "off"),
				}
				refreshVisuals()
			end
			function obj:Refresh()
				refreshVisuals()
			end
			function obj:SetVisible(vis)
				card.Visible = vis == true
			end
			function obj:Alive()
				return card ~= nil and card.Parent ~= nil
			end
			function obj:Destroy()
				if card and card.Parent then
					card:Destroy()
				end
			end
			return obj
		end

		function containerObj:AddSubSection(title)
			if type(title) == "table" then
				title = title.Title or title.Name or title.Text or ""
			end
			title = tostring(title or "")
			local sub = create("Frame", {
				Name = "SubSection_" .. sanitizeKey(title),
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, 24),
				BackgroundTransparency = 1,
				Parent = itemHolder,
			})
			local lbl = create("TextLabel", {
				Position = UDim2.new(0, 6, 0, 4),
				Size = UDim2.new(1, -12, 0, 16),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = title,
				TextColor3 = Theme.Accent,
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				Parent = sub,
			})
			create("Frame", {
				Position = UDim2.new(0, 6, 1, -2),
				Size = UDim2.new(1, -12, 0, 1),
				BackgroundColor3 = Theme.Border,
				BackgroundTransparency = 0.4,
				BorderSizePixel = 0,
				Parent = sub,
			})
			local obj = { Frame = sub }
			function obj:Set(newTitle)
				lbl.Text = tostring(newTitle or "")
			end
			function obj:SetTitle(newTitle)
				lbl.Text = tostring(newTitle or "")
			end
			function obj:SetVisible(vis)
				sub.Visible = vis == true
			end
			function obj:Destroy()
				if sub and sub.Parent then
					sub:Destroy()
				end
			end
			return obj
		end

		function containerObj:AddDivider(text)
			local div = create("Frame", {
				LayoutOrder = nextOrder(),
				Size = UDim2.new(1, 0, 0, 18),
				BackgroundTransparency = 1,
				Parent = itemHolder,
			})
			create("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 4, 0.5, 0),
				Size = UDim2.new(1, -8, 0, 1),
				BackgroundColor3 = Theme.Border,
				BorderSizePixel = 0,
				Parent = div,
			})
			if type(text) == "string" and text ~= "" then
				create("TextLabel", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.new(0.5, 0, 0.5, 0),
					Size = UDim2.new(0, 120, 0, 16),
					BackgroundColor3 = Theme.BgPrimary,
					Font = Theme.FontBold,
					Text = text,
					TextColor3 = Theme.TextMuted,
					TextSize = 10,
					Parent = div,
				})
			end
			return div
		end
	end

	-- ========================================================================
	-- WINDOW OBJECT & TAB / SECTION API
	-- ========================================================================
	local WindowObj = {
		Gui = screenGui,
		Main = mainFrame,
		Tabs = tabs,
	}

	function WindowObj:AddTab(tOpts)
		tOpts = type(tOpts) == "table" and tOpts or {}
		local tabName = tostring(tOpts.Name or tOpts.Title or ("Tab " .. (#tabs + 1)))
		local tabIcon = resolveAsset(tOpts.Icon, Icons.info)

		local tabBtn = create("TextButton", {
			Name = "Tab_" .. sanitizeKey(tabName),
			LayoutOrder = #tabs + 1,
			Size = UDim2.new(1, 0, 0, 36),
			BackgroundColor3 = Theme.BgCard,
			BackgroundTransparency = 0.45,
			Text = "",
			AutoButtonColor = false,
			Parent = tabList,
		})
		addCorner(tabBtn, 8)
		local tabStroke = addStroke(tabBtn, Theme.Border, 1, 0.55)

		local activeBar = create("Frame", {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.new(0, 3, 0, 18),
			BackgroundColor3 = Theme.Accent,
			Visible = false,
			Parent = tabBtn,
		})
		addCorner(activeBar, 2)

		local iconLbl = create("ImageLabel", {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 10, 0.5, 0),
			Size = UDim2.new(0, 16, 0, 16),
			BackgroundTransparency = 1,
			Image = tabIcon,
			ImageColor3 = Theme.TextMuted,
			ScaleType = Enum.ScaleType.Fit,
			Parent = tabBtn,
		})

		local nameLbl = create("TextLabel", {
			Position = UDim2.new(0, 32, 0, 0),
			Size = UDim2.new(1, -38, 1, 0),
			BackgroundTransparency = 1,
			Font = Theme.FontBold,
			Text = tabName,
			TextColor3 = Theme.TextSecondary,
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = tabBtn,
		})

		local page = create("ScrollingFrame", {
			Name = "Page_" .. sanitizeKey(tabName),
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 4,
			ScrollBarImageColor3 = Theme.Accent,
			CanvasSize = UDim2.new(0, 0, 0, 0),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			Visible = false,
			Parent = pageContainer,
		}, {
			addPadding(nil, 10, 14, 12, 12),
			create("UIListLayout", {
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 10),
			}),
		})

		local tabEntry = {
			Name = tabName,
			Button = tabBtn,
			TitleLabel = nameLbl,
			IconLabel = iconLbl,
			Indicator = activeBar,
			Stroke = tabStroke,
			Page = page,
		}
		table.insert(tabs, tabEntry)

		connectClick(tabBtn, function()
			selectTab(tabEntry)
		end)

		if #tabs == 1 then
			selectTab(tabEntry)
		end

		local secOrder = 0
		local TabObj = {
			Page = page,
			Button = tabBtn,
		}

		attachElementsToContainer(TabObj, page, sanitizeKey(tabName))

		function TabObj:AddSection(secName, isOpenDefault)
			if type(secName) == "table" then
				isOpenDefault = secName.Open or secName.Default
				secName = secName.Title or secName.Name or "Section"
			end
			secName = tostring(secName or "Section")
			local isOpen = (isOpenDefault ~= false)
			secOrder = secOrder + 1

			local secFrame = create("Frame", {
				Name = "Section_" .. sanitizeKey(secName),
				LayoutOrder = secOrder,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = Theme.BgSecondary,
				Parent = page,
			})
			addCorner(secFrame, 10)
			addStroke(secFrame, Theme.Border, 1, 0.2)

			create("UIListLayout", {
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 0),
				Parent = secFrame,
			})

			local secHeader = create("TextButton", {
				LayoutOrder = 1,
				Size = UDim2.new(1, 0, 0, 34),
				BackgroundTransparency = 1,
				Text = "",
				AutoButtonColor = false,
				Parent = secFrame,
			})

			create("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 10, 0.5, 0),
				Size = UDim2.new(0, 3, 0, 14),
				BackgroundColor3 = Theme.Accent,
				Parent = secHeader,
			})

			local secTitleLbl = create("TextLabel", {
				Position = UDim2.new(0, 20, 0, 0),
				Size = UDim2.new(1, -50, 1, 0),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = secName,
				TextColor3 = Theme.TextPrimary,
				TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = secHeader,
			})

			local secChevron = create("TextLabel", {
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -12, 0.5, 0),
				Size = UDim2.new(0, 18, 0, 18),
				BackgroundTransparency = 1,
				Font = Theme.FontBold,
				Text = isOpen and "-" or "+",
				TextColor3 = Theme.Accent,
				TextSize = 13,
				Parent = secHeader,
			})

			local secBody = create("Frame", {
				Name = "SectionItems",
				LayoutOrder = 2,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				Visible = isOpen,
				Parent = secFrame,
			}, {
				addPadding(nil, 2, 10, 10, 10),
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					Padding = UDim.new(0, 7),
				}),
			})

			connectClick(secHeader, function()
				isOpen = not isOpen
				secBody.Visible = isOpen
				secChevron.Text = isOpen and "-" or "+"
			end)

			local SectionObj = {
				Frame = secFrame,
				Container = secBody,
			}

			attachElementsToContainer(SectionObj, secBody, sanitizeKey(tabName .. "_" .. secName))

			function SectionObj:SetTitle(newTitle)
				secTitleLbl.Text = tostring(newTitle or "")
			end
			function SectionObj:SetOpen(state)
				isOpen = (state == true)
				secBody.Visible = isOpen
				secChevron.Text = isOpen and "-" or "+"
			end
			function SectionObj:Destroy()
				if secFrame and secFrame.Parent then
					secFrame:Destroy()
				end
			end

			return SectionObj
		end

		return TabObj
	end

	function WindowObj:SaveConfig(name)
		return Config:save(name)
	end
	function WindowObj:QueueAutoSave()
		return Config:scheduleSave()
	end
	function WindowObj:ExportConfig()
		local ok, raw = pcall(function()
			return HttpService:JSONEncode(Config:pack())
		end)
		return ok and type(raw) == "string" and raw or nil
	end
	function WindowObj:ImportConfig(raw)
		if type(raw) ~= "string" or raw == "" then
			return false
		end
		local ok, decoded = pcall(function()
			return HttpService:JSONDecode(raw)
		end)
		if not ok or type(decoded) ~= "table" then
			return false
		end
		decoded._vnhub_schema = CONFIG_SCHEMA_VERSION
		Config.data = decoded
		Config:loadelements()
		Config:save(Config.name)
		return true
	end
	function WindowObj:LoadConfig(name)
		return Config:load(name, false)
	end
	function WindowObj:DeleteConfig(name)
		return Config:delete(name)
	end
	function WindowObj:ResetConfig()
		return Config:reset()
	end
	function WindowObj:GetConfigs()
		return Config:list()
	end
	function WindowObj:SetTitle(t)
		titleLabel.Text = tostring(t or "VN HUB")
	end
	function WindowObj:SetFooter(f)
		subLabel.Text = tostring(f or "")
	end
	function WindowObj:Toggle(state)
		setWindowVisible(state)
	end
	function WindowObj:Destroy()
		if screenGui and screenGui.Parent then
			screenGui:Destroy()
		end
	end

	return WindowObj
end

return Library
