-- ============================================================================
-- VALUE SLIDER HELPER (VNHUB Logarithmic 0..1000 -> $0/s .. $1000B/s)
-- ============================================================================
local VALUE_SLIDER_MAX = 1000
local VALUE_LOG_MIN = 3
local VALUE_LOG_MAX = 12

local function roundSig3(val)
	if val <= 0 then return 0 end
	local mag = 10 ^ (math.floor(math.log10(val)) - 2)
	return math.floor(val / mag + 0.5) * mag
end

local function sliderStepToRawRate(step)
	step = math.clamp(tonumber(step) or 0, 0, VALUE_SLIDER_MAX)
	if step <= 0 then return 0 end
	return roundSig3(10 ^ (VALUE_LOG_MIN + (VALUE_LOG_MAX - VALUE_LOG_MIN) * (step / VALUE_SLIDER_MAX)))
end

local function rawRateToSliderStep(raw)
	raw = tonumber(raw) or 0
	if raw <= 0 then return 0 end
	local pos = (math.log10(raw) - VALUE_LOG_MIN) / (VALUE_LOG_MAX - VALUE_LOG_MIN) * VALUE_SLIDER_MAX
	return math.clamp(math.floor(pos + 0.5), 0, VALUE_SLIDER_MAX)
end

local function formatShortNum(num)
	local fmt = num >= 100 and "%.0f" or (num >= 10 and "%.1f" or "%.2f")
	local s = string.format(fmt, num)
	if string.find(s, ".", 1, true) then
		s = string.gsub(s, "0+$", "")
		s = string.gsub(s, "%.$", "")
	end
	return s
end

local function formatRateShort(raw)
	raw = tonumber(raw) or 0
	if raw <= 0 then return "Tắt ($0/s)" end
	if raw < 1e6 then return "$" .. formatShortNum(raw / 1e3) .. "K/s" end
	if raw < 1e9 then return "$" .. formatShortNum(raw / 1e6) .. "M/s" end
	return "$" .. formatShortNum(raw / 1e9) .. "B/s"
end

local function formatSliderStepRate(step)
	local raw = sliderStepToRawRate(step)
	if raw <= 0 then return "Tắt" end
	if raw < 1e6 then return formatShortNum(raw / 1e3) .. " K/s" end
	if raw < 1e9 then return formatShortNum(raw / 1e6) .. " M/s" end
	return formatShortNum(raw / 1e9) .. " B/s"
end

local UNIT_MULTS = { k = 1e3, m = 1e6, b = 1e9, t = 1e12 }
local function parseSliderRateInput(txt)
	local clean = string.lower(string.gsub(tostring(txt or ""), "[%s,%$/]", ""))
	clean = string.gsub(clean, "s$", "")
	if clean == "" or clean == "off" or clean == "tat" or clean == "tắt" or clean == "0" then
		return 0
	end
	local numStr, unit = string.match(clean, "^([%d%.]+)([kmbt]?)$")
	local n = tonumber(numStr)
	if not n then return nil end
	if unit == "" and n <= VALUE_SLIDER_MAX then
		return n
	end
	return rawRateToSliderStep(n * (UNIT_MULTS[unit] or 1e6))
end

local function addValueSlider(section, opts)
	opts = type(opts) == "table" and opts or {}
	local defRaw = tonumber(opts.DefaultRaw) or 0
	local defStep = rawRateToSliderStep(defRaw)
	return section:AddSlider({
		Flag = opts.Flag or opts.Title,
		Title = opts.Title or "Giá Trị Tối Thiểu ($/s)",
		Content = opts.Content or "Kéo thanh trượt để chọn mức tiền/giây (0 = Tắt lọc giá trị). Có thể nhập 250k, 50m, 1.5b.",
		Min = 0,
		Max = VALUE_SLIDER_MAX,
		Default = defStep,
		Increment = 1,
		ValueFormat = formatSliderStepRate,
		ValueParse = parseSliderRateInput,
		Callback = z(function(stepVal)
			local rawVal = sliderStepToRawRate(stepVal)
			if type(opts.OnRaw) == "function" then
				opts.OnRaw(rawVal)
			end
		end),
	})
end

