			local rows = {}
			for idx, entry in ipairs(st.history) do
				rows[idx] = {
					id = tostring(idx),
					name = entry.player,
					sub = string.format('<font color="#A2A2AE">%s</font>', os.date("!%H:%M:%S", entry.at)),
