					statusSub = entry.outcome,
					button = false,
				}
			end
			historyListUI:Update(rows)
		end
		bi:onChanged(refreshHistory)
		refreshHistory(bi)
		local busyToken
		local lastTick = 0
		local conn
		conn = game:GetService("RunService").Heartbeat:Connect(function()
			if q[9].__VNHUBV4PlayerSteal ~= bi or not playerListUI:Alive() then
				conn:Disconnect()
				return
			end
			local now = os.clock()
			if busyToken and (now - busyToken) < 5 then return end
			if (now - lastTick) < 1 then return end
			lastTick = now
			busyToken = now
			task.spawn(function()
				pcall(function()
					if idSetter then pcall(idSetter, capId) end
					local entries = bi:listEntries()
					if idSetter then pcall(idSetter, capId) end
					if playerListUI:Alive() then
						playerListUI:Update(entries)
					end
				end)
				if busyToken == now then
					busyToken = nil
				end
			end)
		end)
	end
end

