			if upg and type(upg.upgradeBase) == "function" then
				ok, msg = upg.upgradeBase()
			end
			R:Notify({
				Title = "Căn Cứ",
				Content = ok and "Đã nâng cấp căn cứ thành công!" or tostring(msg or "Không thể nâng cấp"),
				Duration = 3,
			})
		end),
	})

	local secTreadmill = C.section(tabFarm, "Máy Tập Tốc Độ (Treadmill)", C.gameIcon("Treadmills", "Directory", "Treadmill", "Icon"), true)
	C.autoTreadmill = secTreadmill:AddToggle({
		Flag = "Farm_AutoTreadmill",
		Title = "Auto Máy Tập",
		Content = "Tự động lên máy tập chạy cày tốc độ khi rảnh rỗi.",
		Default = false,
		Callback = z(D),
	})
	C.treadmillUpgrade = secTreadmill:AddToggle({
		Flag = "Farm_AutoUpgradeTreadmill",
		Title = "Auto Upgrade Máy Tập",
		Content = "Tự động nâng cấp bậc máy tập bằng tiền mặt ngay khi đủ điều kiện.",
		Default = false,
		Callback = z(b),
	})
	C.antiTreadmill = secTreadmill:AddToggle({
		Flag = "Farm_AntiTreadmill",
		Title = "Chống Kẹt Máy Tập (Anti Treadmill)",
		Content = "Tự động nhảy khỏi máy tập nếu bị kẹt và khóa chạy máy tập.",
		Default = false,
		Callback = z(o),
	})

	local secTaskOrder = tabFarm:AddSection({ Title = "Thứ Tự Ưu Tiên Tác Vụ", AlwaysOpen = false, Icon = "activity" })
	local taskIcons = {
		auto_steal = "hand",
		race = "flag",
		star = "star",
		mech_boss = "swords",
		butterfly = "flower",
		auto_place = "egg",
		use_scrambled = "flask-conical",
		auto_sell = "coins",
		treadmill = "activity",
	}
	local taskItems = {}
	for _, id in ipairs(g.DEFAULT) do
		taskItems[#taskItems + 1] = {
			Id = id,
			Title = g.TITLES[id],
			Icon = taskIcons[id],
			Pinned = g.PINNED[id] == true,
			Sub = g.PINNED[id] and "Chạy khi các tác vụ khác đang nghỉ" or nil,
		}
	end
	local function applyTaskOrder(orderList)
		E.TaskOrder = g.sanitize(orderList)
	end
	if type(secTaskOrder.AddPriorityList) == "function" then
		C.taskOrder = secTaskOrder:AddPriorityList({
			Title = "Thứ Tự Ưu Tiên",
			Content = "Tác vụ nằm trên sẽ được ưu tiên điều khiển nhân vật trước.",
			Flag = "TaskOrder",
			Items = taskItems,
			Default = g.DEFAULT,
			EmptyText = "Bật Auto Steal, Auto Place hoặc chức năng khác để sắp xếp tại đây.",
			Callback = z(applyTaskOrder),
		})
	end
end

-- ============================================================================
-- MỤC 3: TRỨNG (Đặt Trứng, Ấp Nở, Dự Đoán Trứng Mod Đẹp, Tự Động Bán + Thanh Kéo, Dung Hợp)
-- ============================================================================
do
	local secPlaceHatch = C.section(tabEgg, "Đặt & Ấp Nở Trứng", C.gameIcon("Assets", "Directory", "Dragon", "Egg", "Icon"), true)
	secPlaceHatch:AddSubSection("Tự Động Đặt Trứng")
	C.autoPlace = secPlaceHatch:AddToggle({
		Flag = "Egg_AutoPlace",
		Title = "Tự Động Đặt Trứng",
		Content = "Tự động mang trứng trong túi đồ đặt vào ô trống tại căn cứ (ưu tiên quả nặng nhất).",
		Default = false,
		Callback = z(ki),
	})
	C.placeRarity = secPlaceHatch:AddDropdown({
		Flag = "Egg_PlaceRarity",
		Title = "Lọc Độ Hiếm Trứng Đặt",
		Content = "Chỉ đặt trứng thuộc các độ hiếm đã chọn (Để trống = Đặt tất cả).",
		Options = A,
		Multi = true,
		Default = {},
		Callback = z(function(val)
			E.PlaceRarities = c(val)
		end),
	})
	secPlaceHatch:AddButton({
		Title = "Đặt Toàn Bộ Trứng Ngay",
		Content = "Chạy 1 lượt đặt toàn bộ trứng vào căn cứ ngay lập tức.",
		Callback = z(function()
			Ji("AutoPlace", L.AutoPlaceLoop)
		end),
	})

	secPlaceHatch:AddSubSection("Tự Động Ấp Nở Trứng")
	C.autoHatch = secPlaceHatch:AddToggle({
		Flag = "Egg_AutoHatch",
		Title = "Tự Động Ấp Nở Trứng",
		Content = "Tự động nở toàn bộ trứng đang đặt tại căn cứ ngay khi vừa chín.",
		Default = false,
		Callback = z(Li),
	})
	secPlaceHatch:AddButton({
		Title = "Ấp Nở Toàn Bộ Trứng Đã Chín Ngay",
		Content = "Nở ngay lập tức mọi quả trứng đã ấp xong tại căn cứ.",
		Callback = z(function()
			Ji("AutoHatch", L.AutoHatchLoop)
		end),
	})

	-- DỰ ĐOÁN TRỨNG (Mod lại từ Trứng Đang Đặt: hiển thị Kg dự đoán, $/s dự đoán, Scale, Đột biến, Đếm ngược)
	local secPredict = tabEgg:AddSection({
		Title = "Dự Đoán Trứng (Trứng Đang Đặt)",
		AlwaysOpen = true,
		Icon = C.gameIcon("Assets", "Directory", "Dragon", "Egg", "Icon"),
	})
	local predictSummary = secPredict:AddParagraph({
		Title = "📊 Thống Kê & Dự Đoán Trứng Trên Sân",
		Content = "Đang quét dữ liệu trứng đang đặt tại căn cứ...",
	})
	local predictList = secPredict.AddActionList and secPredict:AddActionList({
		Title = "Danh sách dự đoán chi tiết từng quả trứng",
		EmptyText = "Chưa có quả trứng nào được đặt tại căn cứ của bạn.",
		VisibleRows = 7,
		ButtonWidth = 78,
	})
	secPredict:AddButton({
		Title = "Nở Ngay Tất Cả Trứng Sẵn Sàng",
		SubTitle = "Bật Nhãn 3D Trên Sân",
		Content = "Nở nhanh các quả đã hoàn tất ấp hoặc bật/tắt nhãn dự đoán 3D trên sân nhà.",
		Callback = z(function()
			Ji("AutoHatch", L.AutoHatchLoop)
			R:Notify({ Title = "Dự Đoán Trứng", Content = "Đang nở toàn bộ trứng đã chín!", Duration = 3 })
		end),
		SubCallback = z(function()
			E.EggESP = true
			local cur = type(E.EspDetails) == "table" and table.clone(E.EspDetails) or { "Name", "Rarity", "Value", "Weight", "Icon" }
			if not table.find(cur, "Placed Eggs") then
				table.insert(cur, "Placed Eggs")
			end
			if not table.find(cur, "Weight") then
				table.insert(cur, "Weight")
			end
			O(cur)
			l(true)
			if C.eggEsp then pcall(function() C.eggEsp:Set(true) end) end
			R:Notify({ Title = "Dự Đoán Trứng", Content = "Đã bật hiển thị dự đoán 3D trên trứng đang đặt!", Duration = 3 })
		end),
	})

	if predictList then
		local rs = game:GetService("ReplicatedStorage")
		local idSetter = q[9].__VNHUBV4IdentitySetter
		local capId = q[9].__VNHUBV4UICapabilityIdentity or 8
		local mutMod, growthPolicy, eggRecordsMod
		pcall(function() mutMod = require(rs.Shared.Modules.Mutations) end)
		pcall(function() growthPolicy = require(rs.Shared.Eggs.PlacedEggGrowthPresentationPolicy) end)
		pcall(function() eggRecordsMod = require(rs.Shared.Eggs.EggRecords) end)

		local function colorHex(col)
			if typeof(col) ~= "Color3" then return "38BDF8" end
			return string.format("%02X%02X%02X", math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
		end

		local specialMuts = { Scrambled = true, Boss = true, Enchanted = true }
		local function mutLabel(mId)
			if mId == "Scrambled" then return "Scrambled" end
			local ok, lbl = pcall(function() return mutMod.LabelOf(mId) end)
			return (ok and type(lbl) == "string" and lbl ~= "") and lbl or tostring(mId)
		end

		local function fmtTime(sec)
			sec = math.max(0, math.floor(sec))
			local hCount, mCount, sCount = math.floor(sec / 3600), math.floor(sec % 3600 / 60), sec % 60
			if hCount > 0 then return string.format("%dh %02dm %02ds", hCount, mCount, sCount) end
			return string.format("%02dm %02ds", mCount, sCount)
		end

		local function fmtWeight(kg)
			kg = tonumber(kg) or 0
			if kg >= 1e6 then return string.format("%.2fM Kg", kg / 1e6) end
			if kg >= 1e3 then return string.format("%.2fK Kg", kg / 1e3) end
			if kg >= 10 then return string.format("%.1f Kg", kg) end
			return string.format("%.2f Kg", kg)
		end

		local function findRenderModel(uid)
			local folder = workspace:FindFirstChild("PlacedEggRenders")
			return folder and folder:FindFirstChild(tostring(q[4].UserId) .. "_" .. tostring(uid))
		end

		local function highlightOrHatchEgg(uid, isReady)
			if isReady then
				pcall(function()
					local eggState = require(rs.Client.EggState)
					if eggState.RequestHatchEgg(uid) then
						eggState.RequestCompleteHatchEgg(uid)
					end
				end)
			end
			local mdl = findRenderModel(uid)
			if not mdl then return isReady end
			local hl = Instance.new("Highlight")
			hl.FillColor = isReady and Color3.fromRGB(74, 222, 128) or Color3.fromRGB(56, 189, 248)
			hl.FillTransparency = 0.45
			hl.OutlineColor = Color3.fromRGB(255, 255, 255)
			hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			hl.Parent = mdl
			task.delay(5, function()
				pcall(function() hl:Destroy() end)
			end)
			return true
		end

		local function buildPredictedEggs()
			local rows = {}
			local ok, ownerEggs = pcall(function()
				return require(rs.Client.EggState).ReadOwnerEggs(q[4].UserId)
			end)
			if not ok or type(ownerEggs) ~= "table" then
				pcall(function()
					predictSummary:SetContent("🥚 Đang đặt: 0/30 quả  •  ✅ Sẵn sàng nở: 0 quả\n💰 Tổng thu nhập dự đoán: $0/s  •  ⚖️ Quả nặng nhất: 0 Kg")
				end)
				return rows
			end

			local nowServer = workspace:GetServerTimeNow()
			local totalPlaced, readyCount, totalRate, maxKg = 0, 0, 0, 0

			for uid, rec in pairs(ownerEggs) do
				local placement = type(rec) == "table" and rec.Placement
				if placement then
					totalPlaced = totalPlaced + 1
					local info = e.resolve(rec)
					local cat = rec.AssetCategory or rec.Category
					local scale = tonumber(rec.AssetScale or rec.Scale) or 1

					-- Tính cân nặng dự đoán (Kg)
					local kg = tonumber(rec.Kg or rec.Weight or rec.kg) or 0
					if kg <= 0 and eggRecordsMod and type(eggRecordsMod.WeightKgForScale) == "function" then
						local okW, calcW = pcall(eggRecordsMod.WeightKgForScale, cat, scale)
						if okW and type(calcW) == "number" and calcW > 0 then
							kg = calcW
						end
					end
					if kg <= 0 then
						kg = math.max(0.1, (tonumber(info.baseWeight) or 1) * (scale ^ 3))
					end
					if kg > maxKg then maxKg = kg end

					-- Tính thu nhập dự đoán ($/s)
					local rate = 0
					pcall(function()
						rate = tonumber(L.rateOf({
							Category = cat,
							Scale = scale,
							Mutations = rec.Mutations or {},
							BaseMutation = rec.BaseMutation,
						})) or 0
					end)
					if rate <= 0 then
						pcall(function()
							rate = tonumber(E:getAreaEggValue(rec)) or 0
						end)
					end
					totalRate = totalRate + rate

					-- Đột biến
					local baseMut = rec.BaseMutation
					local specList, normList, seenMut = {}, {}, {}
					for _, mVal in pairs(type(rec.Mutations) == "table" and rec.Mutations or {}) do
						if not seenMut[mVal] then
							seenMut[mVal] = true
							if mVal ~= baseMut or specialMuts[mVal] then
								specList[#specList + 1] = mutLabel(mVal)
							else
								normList[#normList + 1] = mutLabel(mVal)
							end
						end
					end
					if baseMut and specialMuts[baseMut] and not seenMut[baseMut] then
						specList[#specList + 1] = mutLabel(baseMut)
					end

					-- Thời gian ấp
					local remSec = 0
					if growthPolicy then
						local okG, gSec = pcall(growthPolicy.GetRemainingGrowthSeconds, rec, nowServer)
						remSec = okG and tonumber(gSec) or 0
					end
					local isReady = remSec <= 0
					if isReady then
						readyCount = readyCount + 1
					end

					local hex = colorHex(info.rarityColor)
					local mutText
					if #specList > 0 then
						mutText = '<font color="#4ADE80">🧬 ' .. table.concat(specList, ", ") .. "</font>"
					elseif #normList > 0 then
						mutText = '<font color="#38BDF8">🧬 ' .. table.concat(normList, ", ") .. "</font>"
					else
						mutText = '<font color="#74747F">🧬 Thường (x' .. string.format("%.2f", scale) .. ")</font>"
					end
					if #normList > 0 and #specList > 0 then
						mutText = mutText .. ' <font color="#A2A2AE">[' .. table.concat(normList, ", ") .. "]</font>"
					end

					local timerText = isReady
						and '<font color="#4ADE80">✅ SẴN SÀNG NỞ!</font>'
						or ('⏳ Còn ' .. fmtTime(remSec))

					rows[#rows + 1] = {
						id = tostring(uid),
						name = string.format(
							'<font color="#%s">[%s] %s</font> <font color="#A2A2AE">• x%.2f</font>',
							hex,
							tostring(info.rarity or "?"),
							tostring(info.name or cat or "Egg"),
							scale
						),
						sub = string.format(
							'<font color="#FBBF24">⚖️ %s</font>  •  <font color="#4ADE80">💰 %s</font>',
							fmtWeight(kg),
							formatRateShort(rate)
						),
						status = mutText,
						statusSub = timerText,
						button = isReady and "Nở Ngay" or "Định Vị",
						buttonColor = isReady and "green" or "accent",
						rank = info.rarityRank or 0,
						rate = rate,
						kg = kg,
						ready = isReady,
						onClick = function(_, setBtn)
							local okAct = highlightOrHatchEgg(uid, isReady)
							setBtn(okAct and (isReady and "Đã Nở" or "Đã Thấy") or "Xa", okAct and "green" or "red")
							task.delay(1.5, function()
								pcall(setBtn, isReady and "Nở Ngay" or "Định Vị", isReady and "green" or "accent")
							end)
						end,
					}
				end
			end

			table.sort(rows, function(aRow, bRow)
				if aRow.ready ~= bRow.ready then return aRow.ready end
				if aRow.rate ~= bRow.rate then return aRow.rate > bRow.rate end
				if aRow.rank ~= bRow.rank then return aRow.rank > bRow.rank end
				return aRow.kg > bRow.kg
			end)

			pcall(function()
				predictSummary:SetContent(string.format(
					"🥚 Đang đặt: %d/30 quả  •  ✅ Sẵn sàng nở: %d quả\n💰 Tổng thu nhập dự đoán: %s  •  ⚖️ Quả nặng nhất: %s",
					totalPlaced,
					readyCount,
					formatRateShort(totalRate),
					fmtWeight(maxKg)
				))
			end)

			return rows
		end

		local busyToken
		local lastTick = 0
		local conn
		conn = game:GetService("RunService").Heartbeat:Connect(function()
			if not predictList:Alive() then
				conn:Disconnect()
				return
			end
			local now = os.clock()
			if busyToken and (now - busyToken) < 5 then return end
			if (now - lastTick) < 1 then return end
			lastTick = now
			busyToken = now
			task.spawn(function()
				pcall(function()
					if idSetter then pcall(idSetter, capId) end
					local listData = buildPredictedEggs()
					if idSetter then pcall(idSetter, capId) end
					if predictList:Alive() then
						predictList:Update(listData)
					end
				end)
				if busyToken == now then
					busyToken = nil
				end
			end)
		end)
	end

	-- TỰ ĐỘNG BÁN (Auto Sell Pet & Egg + Lọc Độ Hiếm + Thanh Kéo Giá Trị)
	local secSell = C.section(tabEgg, "Tự Động Bán (Pet & Trứng)", C.gameIcon("Currency", "Directory", "Money", "Icon"), true)
	secSell:AddSubSection("Bán Thú Cưng (Auto Sell Pet)")
	C.autoSell = secSell:AddToggle({
		Flag = "Sell_AutoSellPet",
		Title = "Tự Động Bán Thú Cưng",
		Content = "Tự động bán các thú cưng khớp bộ lọc bên dưới (Giữ lại pet đang trang bị, đặt trên sân hoặc đã khóa yêu thích).",
		Default = false,
		Callback = z(di),
	})
	m = secSell:AddDropdown({
		Flag = "Sell_PetRarities",
		Title = "Lọc Độ Hiếm Thú Cưng Bán",
		Content = "Chọn độ hiếm thú cưng muốn bán (Chọn All để bán mọi độ hiếm).",
		Options = J(A),
		Multi = true,
		Default = {},
		Callback = z(function(val)
			E.SellRarities = c(val)
		end),
	})
	k = secSell:AddDropdown({
		Flag = "Sell_PetNames",
		Title = "Lọc Tên Thú Cưng Bán (Tùy Chọn)",
		Content = "Chọn loài cụ thể muốn bán (Để trống = Bán mọi loài khớp độ hiếm hoặc thanh kéo giá trị).",
		Options = X,
		Multi = true,
		Default = {},
		Callback = z(function(val)
			E.SellNames = c(val)
		end),
	})
	C.sellPetValue = addValueSlider(secSell, {
		Flag = "Sell_PetValueSlider",
		Title = "Thanh Kéo Giá Trị Bán Pet (Tối Đa $/s)",
		Content = "Chỉ bán thú cưng có thu nhập $/s thấp hơn hoặc bằng mức này (0 = Không giới hạn giá trị).",
		DefaultRaw = 0,
		OnRaw = function(rawVal)
			E.SellPetMaxRate = rawVal
		end,
	})
	secSell:AddButton({
		Title = "Bán Thú Cưng Ngay (1 Lượt)",
		Content = "Chạy ngay 1 lượt bán thú cưng theo bộ lọc trên.",
		Callback = z(function()
			Ji("AutoSell", L.startAutoSellLoop)
		end),
	})

	secSell:AddSubSection("Bán Trứng Trong Túi (Auto Sell Egg)")
	C.autoSellEgg = secSell:AddToggle({
		Flag = "Sell_AutoSellEgg",
		Title = "Tự Động Bán Trứng",
		Content = "Tự động bán các quả trứng chưa đặt trong túi đồ khớp độ hiếm và thanh kéo giá trị bên dưới.",
		Default = false,
		Callback = z(Di),
	})
	p = secSell:AddDropdown({
		Flag = "Sell_EggRarities",
		Title = "Lọc Độ Hiếm Trứng Bán",
		Content = "Chọn độ hiếm trứng muốn bán (Chọn All để bán mọi độ hiếm).",
		Options = J(A),
		Multi = true,
		Default = {},
		Callback = z(function(val)
			E.SellEggRarities = c(val)
		end),
	})
	C.sellEggValue = addValueSlider(secSell, {
		Flag = "Sell_EggValueSlider",
		Title = "Thanh Kéo Giá Trị Bán Trứng (Tối Đa $/s)",
		Content = "Chỉ bán trứng có giá trị $/s thấp hơn hoặc bằng mức này (0 = Không giới hạn giá trị).",
		DefaultRaw = 0,
		OnRaw = function(rawVal)
			E.SellEggMaxRate = rawVal
		end,
	})
	secSell:AddButton({
		Title = "Bán Trứng Ngay (1 Lượt)",
		Content = "Chạy ngay 1 lượt bán trứng theo bộ lọc trên.",
		Callback = z(function()
			Ji("AutoSellEgg", L.startAutoSellEggLoop)
		end),
	})

	-- DUNG HỢP THÚ CƯNG & KHÓA BẢO VỆ (Mod lại gọn đẹp)
	local secFuse = C.section(tabEgg, "Dung Hợp & Khóa Thú Cưng", C.gameIcon("FallenPowerUp", "Kinds", "Fusion", "Icon"), false)
	secFuse:AddSubSection("Máy Dung Hợp (Pet Fusion)")
	C.autoFuse = secFuse:AddToggle({
		Flag = "Fuse_AutoFuse",
		Title = "Tự Động Dung Hợp Thú Cưng (Auto Fuse)",
		Content = "Tự động ghép 3 thú cưng cùng loại vào máy Fusion (Không bao giờ dùng pet đang trang bị hoặc đã khóa yêu thích).",
		Default = false,
		Callback = z(Ci),
	})
	C.fuseRule = secFuse:AddDropdown({
		Flag = "Fuse_Rule",
		Title = "Chế Độ Dung Hợp",
