-- MỤC 6: ADMIN ABUSE (Tăng Tốc Tối Đa, Bắt Trứng Tức Thì, Infinity Jump + Capture The Egg, Admin Treadmill, Minigame Eggs, Cursed Island Wars)
-- ============================================================================
local vnhubIslandWarsSec
do
	local secAdminCore = C.section(tabAdmin, "Chức Năng Admin Abuse Chính", C.gameIcon("Gears", "Directory", "GravityDisruptor", "Icon"), true)
	C.adminBoost = secAdminCore:AddToggle({
		Flag = "Admin_MaxSpeedBoost",
		Title = "Tăng Tốc Tối Đa (Admin Abuse Boost)",
		Content = "Tăng tốc độ di chuyển và tốc độ Auto Steal lên mức tối đa trong sự kiện Admin Abuse.",
		Default = false,
		Callback = z(ei),
	})
	C.instantGrab = secAdminCore:AddToggle({
		Flag = "Admin_InstantGrab",
		Title = "Bắt Trứng Tức Thì (Instant Grab)",
		Content = "Nhặt trứng trên sân ngay lập tức khi chạm vào mà không cần giữ phím chờ.",
		Default = false,
		Callback = z(Ii),
	})
	C.infiniteJump = secAdminCore:AddToggle({
		Flag = "Admin_InfiniteJump",
		Title = "Nhảy Vô Hạn Trên Không (Infinity Jump)",
		Content = "Cho phép nhảy liên tục trên không trung không giới hạn.",
		Default = false,
		Callback = z(Gi),
	})
	C.noclip = secAdminCore:AddToggle({
		Flag = "Admin_Noclip",
		Title = "Đi Xuyên Tường (Noclip)",
		Content = "Đi xuyên qua mọi bức tường và chướng ngại vật.",
		Default = false,
		Callback = z(gi),
	})
	C.antiGuardKnockback = secAdminCore:AddToggle({
		Flag = "Admin_AntiGuardKnockback",
		Title = "Chống Đẩy Lùi Bảo Vệ (Anti Guard Knockback)",
		Content = "Miễn nhiễm lực văng khi bị bảo vệ đánh trúng.",
		Default = false,
		Callback = z(h),
	})

	-- 1. CAPTURE THE EGG (VNHUB + VNHub)
	local secCapture = C.section(tabAdmin, "Capture The Egg", C.gameIcon("CaptureTheEgg", "BroadcastIconImage"), true)
	local captureStatusPara = secCapture:AddParagraph({
		Title = "Trạng Thái Capture The Egg",
		Content = "Off",
	})
	local capTakeFromHolder = false
	local capHoldHeight = 45
	local capKeepAway = 45
	C.autoStealCapture = secCapture:AddToggle({
		Flag = "Admin_CaptureTheEgg",
		Title = "Auto Capture Event Egg",
		Content = "Tự động cướp trứng sự kiện Capture The Egg và bay giữ trứng trên cao tránh người chơi khác.",
		Default = false,
		Callback = z(function(val)
			zi(val)
			f(val)
			if not val then
				pcall(function() captureStatusPara:SetContent("Off") end)
			else
				pcall(function() captureStatusPara:SetContent("Đang chờ sự kiện Capture The Egg...") end)
			end
		end),
	})
	C.capTakeHolder = secCapture:AddToggle({
		Flag = "Admin_CaptureTakeHolder",
		Title = "Take It From The Holder (Cướp Từ Người Đang Giữ)",
		Content = "Tự động cầm gậy đuổi đánh người đang giữ trứng sự kiện để cướp lại.",
		Default = false,
		Callback = z(function(val)
			capTakeFromHolder = val == true
		end),
	})
	C.capHoldHeight = secCapture:AddSlider({
		Flag = "Admin_CaptureHoldHeight",
		Title = "Hold Height (Độ Cao Giữ Trứng)",
		Content = "Độ cao lơ lửng trên không khi đang ôm trứng sự kiện.",
		Min = 20,
		Max = 120,
		Default = 45,
		Increment = 1,
		Callback = z(function(val)
			capHoldHeight = math.clamp(tonumber(val) or 45, 20, 120)
		end),
	})
	C.capKeepAway = secCapture:AddSlider({
		Flag = "Admin_CaptureKeepAway",
		Title = "Keep Away Distance (Khoảng Cách Né Người)",
		Content = "Khoảng cách tự động né người chơi khác và bảo vệ khi đang giữ trứng.",
		Min = 20,
		Max = 150,
		Default = 45,
		Increment = 1,
		Callback = z(function(val)
			capKeepAway = math.clamp(tonumber(val) or 45, 20, 150)
		end),
	})

	-- Loop hỗ trợ Capture The Egg (Take From Holder & Hold Height / Keep Away)
	task.spawn(function()
		while q[11]() do
			if E.AutoStealCapture then
				pcall(function()
					local uid = workspace:GetAttribute("Event_CaptureTheEggUid")
					local live = workspace:GetAttribute("Event_CaptureTheEgg") == true or workspace:GetAttribute("Event_CaptureTheEggGameplay") == true
					if type(uid) == "string" and uid ~= "" then
						local eggState = require(q[2].Client.EggState)
						local rec = eggState.ReadFieldEgg and eggState.ReadFieldEgg(uid)
						local carrierId = type(rec) == "table" and tonumber(rec.CarrierUserId) or nil
						local root = q[4].Character and q[4].Character:FindFirstChild("HumanoidRootPart")
						if carrierId == q[4].UserId and root then
							captureStatusPara:SetContent(string.format("🟢 Đang giữ trứng sự kiện (Độ cao %d st • Né %d st)", capHoldHeight, capKeepAway))
							-- Giữ độ cao theo thanh trượt
							local targetY = 70 + capHoldHeight
							if math.abs(root.Position.Y - targetY) > 3 then
								root.CFrame = CFrame.new(root.Position.X, targetY, root.Position.Z) * root.CFrame.Rotation
								root.AssemblyLinearVelocity = Vector3.zero
							end
						elseif carrierId and carrierId > 0 and carrierId ~= q[4].UserId then
							local holderPlr = q[1]:GetPlayerByUserId(carrierId)
							if capTakeFromHolder and holderPlr and bi and type(bi._chase) == "function" then
								captureStatusPara:SetContent("⚔️ Đang đuổi đánh " .. tostring(holderPlr.DisplayName) .. " để cướp trứng sự kiện!")
							else
								captureStatusPara:SetContent("⏳ " .. tostring(holderPlr and holderPlr.DisplayName or "Người chơi khác") .. " đang giữ trứng sự kiện")
							end
						else
							captureStatusPara:SetContent("🎯 Đang bay tới nhặt trứng sự kiện Capture The Egg!")
						end
					else
						captureStatusPara:SetContent(live and "🟡 Sự kiện đang mở, chờ trứng xuất hiện..." or "⏳ Đang chờ sự kiện Capture The Egg")
					end
				end)
			end
			task.wait(0.35)
		end
	end)

	-- 2. ADMIN TREADMILL (VNHUB)
	local secAdminTreadmill = C.section(tabAdmin, "Admin Treadmill", C.gameIcon("Treadmills", "Directory", "Treadmill", "Icon"), true)
	local adminTreadmillPara = secAdminTreadmill:AddParagraph({
		Title = "Trạng Thái Admin Treadmill",
		Content = "Off",
	})
	local useAdminTreadmill = false
	C. setUseAdminTreadmill = function(val)
		useAdminTreadmill = val == true
		if not useAdminTreadmill then
			pcall(function() adminTreadmillPara:SetContent("Off") end)
		else
			pcall(function() adminTreadmillPara:SetContent("Đang tìm máy tập Admin Treadmill...") end)
		end
	end
	C.useAdminTreadmill = secAdminTreadmill:AddToggle({
		Flag = "Admin_UseAdminTreadmill",
		Title = "Use Admin Treadmill (Tự Chạy Máy Tập Admin)",
		Content = "Tự động tìm và chạy trên máy tập Admin Treadmill (xBoost cực lớn) ngay khi xuất hiện trên bản đồ.",
		Default = false,
		Callback = z(C.setUseAdminTreadmill),
	})

	task.spawn(function()
		local beltNames = { treadmillbottom = 1, bottom = 2, belt = 3, conveyor = 4 }
		local fallbackSpot = Vector3.new(540.05, 68.58, -369.7)
		local function findAdminBeltPart()
			local adminMdl = workspace:FindFirstChild("AdminTreadmill")
			local boostVal = workspace:GetAttribute("AdminBoost_Treadmill")
			if not adminMdl and not (type(boostVal) == "number" and boostVal > 1) then
				return nil
			end
			if adminMdl then
				local bestScore, bestArea, bestPart = 1e9, -1, nil
				for _, desc in ipairs(adminMdl:GetDescendants()) do
					if desc:IsA("BasePart") then
						local sc = beltNames[string.lower(desc.Name)]
						local area = desc.Size.X * desc.Size.Z
						if sc and desc.Size.Y <= 2 and area >= 16 and (sc < bestScore or (sc == bestScore and area > bestArea)) then
							bestScore, bestArea, bestPart = sc, area, desc
						end
					end
				end
				if bestPart then return bestPart.Position + Vector3.new(0, 3, 0), true end
				local okP, piv = pcall(function() return adminMdl:GetPivot().Position end)
				if okP and piv then return piv + Vector3.new(0, 3, 0), true end
			end
			return fallbackSpot + Vector3.new(0, 3, 0), false
		end

		while q[11]() do
			if useAdminTreadmill then
				pcall(function()
					if g.stealCarrying() or g.bossFighting() or E.IsPlacing then
						adminTreadmillPara:SetContent("⏳ Đang nhường cho tác vụ ưu tiên...")
						return
					end
					local spot, foundModel = findAdminBeltPart()
					if not spot then
						adminTreadmillPara:SetContent("⏳ Đang chờ Admin Treadmill xuất hiện...")
						return
					end
					local char = q[4].Character
					local root = char and char:FindFirstChild("HumanoidRootPart")
					local hum = char and char:FindFirstChildOfClass("Humanoid")
					if root and hum then
						local dist = (Vector3.new(root.Position.X, 0, root.Position.Z) - Vector3.new(spot.X, 0, spot.Z)).Magnitude
						if dist > 8 then
							adminTreadmillPara:SetContent("🏃 Đang di chuyển tới Admin Treadmill...")
							root.CFrame = CFrame.new(spot)
							root.AssemblyLinearVelocity = Vector3.zero
						else
							adminTreadmillPara:SetContent(foundModel and "🟢 Đang chạy trên Admin Treadmill!" or "🟢 Đang đứng tại vị trí Admin Treadmill")
							hum:Move(Vector3.new(0, 0, -1), false)
						end
					end
				end)
			end
			task.wait(0.5)
		end
	end)

	-- 3. MINIGAME EGGS (VNHUB: Red Light Green Light & T-Rex Run)
	local secMinigame = C.section(tabAdmin, "Minigame Eggs", C.gameIcon("Assets", "Directory", "TRex", "Egg", "Icon"), true)
	local minigamePara = secMinigame:AddParagraph({
		Title = "Trạng Thái Minigame Eggs",
		Content = "Off",
	})
	local autoMinigameEgg = false
	C.setAutoMinigameEgg = function(val)
		autoMinigameEgg = val == true
		if not autoMinigameEgg then
			pcall(function() minigamePara:SetContent("Off") end)
		else
			pcall(function() minigamePara:SetContent("Đang chờ Red Light Green Light hoặc T-Rex Run...") end)
		end
	end
	C.autoMinigameEgg = secMinigame:AddToggle({
		Flag = "Admin_AutoMinigameEgg",
		Title = "Auto Steal Minigame Egg",
		Content = "Tự động phát hiện và trộm trứng sự kiện Red Light Green Light & T-Rex Run ngay khi xuất hiện.",
		Default = false,
		Callback = z(C.setAutoMinigameEgg),
	})

	task.spawn(function()
		local mgSpecs = {
			{ Flag = "Event_RedLightGreenLight", Prefix = "RLGL", Name = "Red Light Green Light" },
			{ Flag = "Event_TrexRun", Prefix = "TrexRun", Name = "T-Rex Run" },
		}
		while q[11]() do
			if autoMinigameEgg then
				pcall(function()
					local activeEv = nil
					for _, sp in ipairs(mgSpecs) do
						if workspace:GetAttribute(sp.Flag) == true or typeof(workspace:GetAttribute(sp.Prefix .. "_EggPosition")) == "Vector3" then
							activeEv = sp
							break
						end
					end
					if not activeEv then
						minigamePara:SetContent("⏳ Đang chờ Red Light Green Light hoặc T-Rex Run")
						return
					end
					local eggPos = workspace:GetAttribute(activeEv.Prefix .. "_EggPosition")
					local carrier = workspace:GetAttribute(activeEv.Prefix .. "_CarrierUserId")
					if carrier == q[4].UserId then
						minigamePara:SetContent("🟢 [" .. activeEv.Name .. "] Đang mang trứng minigame về nhà!")
						return
					elseif type(carrier) == "number" and carrier > 0 then
						minigamePara:SetContent("⚠️ [" .. activeEv.Name .. "] Người chơi khác đang cầm trứng")
						return
					elseif typeof(eggPos) ~= "Vector3" then
						minigamePara:SetContent("🟡 [" .. activeEv.Name .. "] Đang chờ trứng đáp xuống...")
						return
					end
					local eggState = require(q[2].Client.EggState)
					local snap = eggState.ReadFieldEggs and eggState.ReadFieldEggs()
					local records = type(snap) == "table" and snap.Records or nil
					local bestUid, bestDist = nil, 45
					if type(records) == "table" then
						for _, r in pairs(records) do
							if type(r) == "table" and type(r.Uid) == "string" and r.State ~= "Carried" and r.State ~= "Claimed" then
								local cf = typeof(r.BottomCFrame) == "CFrame" and r.BottomCFrame or (typeof(r.BoundsCFrame) == "CFrame" and r.BoundsCFrame or nil)
								if cf then
									local d2 = Vector3.new(cf.Position.X - eggPos.X, 0, cf.Position.Z - eggPos.Z).Magnitude
									if d2 < bestDist then
										bestDist, bestUid = d2, r.Uid
									end
								end
							end
						end
					end
					if bestUid then
						minigamePara:SetContent("🎯 [" .. activeEv.Name .. "] Đang lao tới lấy trứng minigame!")
						if a then
							a.tweenRecoveryUid = bestUid
							if not E.AutoSteal then
								_(true)
							else
								pcall(a._schedule, a)
							end
						end
					else
						minigamePara:SetContent("🔍 [" .. activeEv.Name .. "] Trứng đã đáp, đang quét UID...")
					end
				end)
			end
			task.wait(0.4)
		end
	end)

	-- 4. CURSED ISLAND WARS (VNHUB - gắn vào b9_11328.luau)
	vnhubIslandWarsSec = C.section(tabAdmin, "Cursed Island Wars", "swords", true)
end

-- ============================================================================
-- KHỞI CHẠY MODULE VNHUB (Halloween Dimension, Monsters, Ghost Dog & Fishing, Phantom Express, Cursed Island Wars)
-- ============================================================================
do
	local vnhubInitCallbacks = {}
	local function wrapSectionForVNHUB(vnSec, secPrefix)
		local adapter = {}
		function adapter:CreateText(opts)
			opts = type(opts) == "table" and opts or {}
			local para = vnSec:AddParagraph({
				Title = tostring(opts.Name or "Trạng Thái"),
				Content = tostring(opts.Text or "Off"),
			})
			return {
				Para = para,
				Set = function(_, txt)
					pcall(para.SetContent, para, tostring(txt or ""))
				end,
			}
		end
		function adapter:CreateToggle(opts)
			opts = type(opts) == "table" and opts or {}
			local handle = { Value = false }
			local ctrl = vnSec:AddToggle({
				Flag = secPrefix .. "_Tgl_" .. tostring(opts.Name or "Toggle"),
				Title = tostring(opts.Name or "Toggle"),
				Content = tostring(opts.Note or ""),
				Default = false, -- Luôn tắt mặc định theo yêu cầu
				Callback = function(val)
					if type(F) == "function" then F() end
					local bVal = val == true
					handle.Value = bVal
					if not I and type(opts.Callback) == "function" then
						pcall(opts.Callback, bVal)
					end
				end,
			})
			handle.Ctrl = ctrl
			if ctrl and ctrl.Value ~= nil then
				handle.Value = ctrl.Value == true
			end
			function handle:Get()
				if ctrl and ctrl.Value ~= nil then
					self.Value = ctrl.Value == true
				end
				return self.Value == true
			end
			function handle:Set(v)
				local bVal = v == true
				self.Value = bVal
				if ctrl and type(ctrl.Set) == "function" then
					pcall(ctrl.Set, ctrl, bVal)
				elseif type(opts.Callback) == "function" then
					pcall(opts.Callback, bVal)
				end
			end
			if type(opts.Callback) == "function" then
				table.insert(vnhubInitCallbacks, { handle = handle, cb = opts.Callback })
			end
			return handle
		end
		function adapter:CreateSlider(opts)
			opts = type(opts) == "table" and opts or {}
			local defVal = tonumber(opts.Default) or tonumber(opts.Min) or 0
			local handle = { Value = defVal }
			local ctrl = vnSec:AddSlider({
				Flag = secPrefix .. "_Sld_" .. tostring(opts.Name or "Slider"),
				Title = tostring(opts.Name or "Slider"),
				Content = tostring(opts.Note or ""),
				Min = tonumber(opts.Min) or 0,
				Max = tonumber(opts.Max) or 100,
				Default = defVal,
				Increment = tonumber(opts.Increment) or 1,
				Callback = function(val)
					if type(F) == "function" then F() end
					handle.Value = tonumber(val) or defVal
					if not I and type(opts.Callback) == "function" then
						pcall(opts.Callback, handle.Value)
					end
				end,
			})
			handle.Ctrl = ctrl
			if ctrl and ctrl.Value ~= nil then
				handle.Value = tonumber(ctrl.Value) or defVal
			end
			function handle:Get()
				if ctrl and ctrl.Value ~= nil then
					self.Value = tonumber(ctrl.Value) or self.Value
				end
				return self.Value
			end
			function handle:Set(v)
				self.Value = tonumber(v) or defVal
				if ctrl and type(ctrl.Set) == "function" then
					pcall(ctrl.Set, ctrl, self.Value)
				elseif type(opts.Callback) == "function" then
					pcall(opts.Callback, self.Value)
				end
			end
			if type(opts.Callback) == "function" then
				table.insert(vnhubInitCallbacks, { handle = handle, cb = opts.Callback })
			end
			return handle
		end
		function adapter:CreateDropdown(opts)
			opts = type(opts) == "table" and opts or {}
			local list = type(opts.Options) == "table" and opts.Options or {}
			local defVal = opts.Default or list[1]
			local handle = { Value = defVal }
			local ctrl = vnSec:AddDropdown({
				Flag = secPrefix .. "_Drp_" .. tostring(opts.Name or "Dropdown"),
				Title = tostring(opts.Name or "Dropdown"),
				Content = tostring(opts.Note or ""),
				Options = list,
				Default = defVal,
				Multi = false,
				Callback = function(val)
					if type(F) == "function" then F() end
					local pick = type(val) == "table" and val[1] or val
					handle.Value = pick
					if not I and type(opts.Callback) == "function" then
						pcall(opts.Callback, pick)
					end
				end,
			})
			handle.Ctrl = ctrl
			if ctrl and ctrl.Value ~= nil then
				handle.Value = type(ctrl.Value) == "table" and ctrl.Value[1] or ctrl.Value
			end
			function handle:Get()
				if ctrl and ctrl.Value ~= nil then
					self.Value = type(ctrl.Value) == "table" and ctrl.Value[1] or ctrl.Value
				end
				return self.Value
			end
			function handle:Set(v)
				self.Value = v
				if ctrl and type(ctrl.Set) == "function" then
					pcall(ctrl.Set, ctrl, v)
				elseif type(opts.Callback) == "function" then
					pcall(opts.Callback, v)
				end
			end
			if type(opts.Callback) == "function" then
				table.insert(vnhubInitCallbacks, { handle = handle, cb = opts.Callback })
			end
			return handle
		end
		function adapter:CreateMultiDropdown(opts)
			opts = type(opts) == "table" and opts or {}
			local list = type(opts.Options) == "table" and opts.Options or {}
			local defVal = type(opts.Default) == "table" and opts.Default or {}
			local handle = { Value = defVal }
			local ctrl = vnSec:AddDropdown({
				Flag = secPrefix .. "_MDrp_" .. tostring(opts.Name or "MultiDropdown"),
				Title = tostring(opts.Name or "MultiDropdown"),
				Content = tostring(opts.Note or ""),
				Options = list,
				Default = defVal,
				Multi = true,
				Callback = function(val)
					if type(F) == "function" then F() end
					local clean = c(val)
					handle.Value = clean
					if not I and type(opts.Callback) == "function" then
						pcall(opts.Callback, clean)
					end
				end,
			})
			handle.Ctrl = ctrl
			if ctrl and ctrl.Value ~= nil then
				handle.Value = c(ctrl.Value)
			end
			function handle:Get()
				if ctrl and ctrl.Value ~= nil then
					self.Value = c(ctrl.Value)
				end
				return self.Value
			end
			function handle:SetOptions(newOpts, newSel)
				self.Value = type(newSel) == "table" and newSel or self.Value
				if ctrl and type(ctrl.Refresh) == "function" then
					pcall(ctrl.Refresh, ctrl, newOpts, self.Value)
				end
				if type(opts.Callback) == "function" then
					pcall(opts.Callback, self.Value)
				end
			end
			if type(opts.Callback) == "function" then
				table.insert(vnhubInitCallbacks, { handle = handle, cb = opts.Callback })
			end
			return handle
		end
		function adapter:CreateValueSlider(opts)
			opts = type(opts) == "table" and opts or {}
			local sld = addValueSlider(vnSec, {
				Flag = secPrefix .. "_ValSld_" .. tostring(opts.Name or "MinValue"),
				Title = tostring(opts.Name or "Min Value") .. " ($/s)",
				Content = tostring(opts.Note or "Kéo thanh trượt để lọc giá trị $/s tối thiểu (0 = Tắt)."),
				DefaultRaw = 0,
				OnRaw = opts.OnRaw,
			})
			if sld and type(opts.OnRaw) == "function" then
				table.insert(vnhubInitCallbacks, {
					handle = {
						Get = function()
							return sliderStepToRawRate(sld.Value or 0)
						end,
					},
					cb = opts.OnRaw,
				})
			end
			return sld
		end
		return adapter
	end

	local N = {
		[0] = table.pack,
		Qc = function(_, tbl)
			return table.unpack(tbl, 1, tbl.n or #tbl)
		end,
		uc = function(_, dst, off, ...)
			local packed = table.pack(...)
			table.move(packed, 1, packed.n, off + 1, dst)
		end,
	}

	local vnhubTasks = {}
	local vnhubWoke = true
	local vnhubIdx = 0
	local vnhubRunner = {
		Add = function(fn)
			local tObj = { Run = fn, Gap = 0.35, Idle = 5, Repeat = false, Hold = 0, Woke = true }
			table.insert(vnhubTasks, tObj)
			return tObj
		end,
		Wake = function()
			vnhubWoke = true
		end,
		Backoff = function(tObj, sec)
			if tObj then tObj.Hold = tonumber(sec) or 6 end
		end,
	}

	local vnhubCleanups = {}
	local function registerVNHUBCleanup(fn)
		if type(fn) == "function" then
			table.insert(vnhubCleanups, fn)
		end
	end

	local rs = q[2]
	local pkgNet = rs:FindFirstChild("Packages") and rs.Packages:FindFirstChild("Networking") or rs:FindFirstChild("Networking", true)
	local netProxy = {
		FindFirstChild = function(_, name)
			name = tostring(name or "")
			if pkgNet then
				local found = pkgNet:FindFirstChild(name) or pkgNet:FindFirstChild(name, true)
				if found then return found end
				local cur = pkgNet
				for seg in string.gmatch(name, "[^/]+") do
					cur = cur and cur:FindFirstChild(seg)
				end
				if cur and cur ~= pkgNet then return cur end
			end
			local direct = rs:FindFirstChild(name, true)
			if direct then return direct end
			local curRs = rs
			for seg in string.gmatch(name, "[^/]+") do
				curRs = curRs and curRs:FindFirstChild(seg)
			end
			if curRs and curRs ~= rs then return curRs end
			return nil
		end,
	}

	local runSvc = q[5]
	local runProxy = setmetatable({
		VNHUBDead = function()
			return not q[11]()
		end,
	}, { __index = runSvc })

	local rawSaveMod = (function() local ok, m = pcall(function() return require(rs.Shared.Save) end); return ok and type(m) == "table" and m or {} end)()
	local areaEggCycleMod = (function() local ok, m = pcall(function() return require(rs.Shared.Util.AreaEggCycle) end); return ok and type(m) == "table" and m or {} end)()
	local areaEggResetWallMod = (function() local ok, m = pcall(function() return require(rs.Client.AreaEggResetWall) end); return ok and type(m) == "table" and m or {} end)()
	local areaEggResetCycleMod = (function() local ok, m = pcall(function() return require(rs.Shared.Util.AreaEggResetCycle) end); return ok and type(m) == "table" and m or {} end)()

	local sharedTbl = {
		Save = {
			Get = function(...)
				local fn = rawSaveMod.Get or rawSaveMod.Peek
				if type(fn) == "function" then return fn(...) end
				return nil
			end,
			Peek = function(...)
				local fn = rawSaveMod.Peek or rawSaveMod.Get
				if type(fn) == "function" then return fn(...) end
				return nil
			end,
			FieldSignal = function(...)
				local fn = rawSaveMod.FieldSignal or rawSaveMod.Watch
				if type(fn) == "function" then return fn(...) end
				return nil
			end,
		},
		Assets = (function() local ok, m = pcall(function() return require(rs.Data.Assets) end); return ok and m or {} end)(),
		AreaEggCycle = areaEggCycleMod,
		HalloweenSection = wrapSectionForVNHUB(vnhubHalloweenSec, "VNHUB_HwDim"),
		MonsterSection   = wrapSectionForVNHUB(vnhubMonsterSec, "VNHUB_HwMon"),
		GhostDogSection  = wrapSectionForVNHUB(vnhubGhostDogSec, "VNHUB_GhostDog"),
		TrainSection     = wrapSectionForVNHUB(vnhubTrainSec, "VNHUB_Train"),
	}

	local batKeywords = { "bat", "katana", "axe", "staff", "club", "hammer", "sword", "blade", "slap" }
	local function isWeaponBat(tool)
		if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then return false end
		if tool:GetAttribute("IsBat") == true then return true end
		local lname = string.lower(tool.Name)
		for _, kw in ipairs(batKeywords) do
			if string.find(lname, kw, 1, true) then return true end
		end
		return false
	end

	local vnhubEnv = {}
	vnhubEnv.Movement = { Owner = nil, CaptureUntil = 0 }
	vnhubEnv.MovementWaiting = {}
	vnhubEnv.Steal = { Active = false, Carrying = false, Wanted = false, WantedRank = 99, WantedValue = 0, Enabled = false }
	vnhubEnv.SafeCarry = { LastDelivered = 0 }
	vnhubEnv.Treadmill = {
		Riding = false,
		Wanted = function() return E.AutoTreadmillIdle == true end,
	}
	vnhubEnv.AdminAbuse = { OnAdmin = false }
	vnhubEnv.Priority = {
		Rank = {
			StealFilter = 1, Star = 2, Race = 3, Butterfly = 4, StealWisp = 5,
			StealIndex = 6, StealLab = 7, Place = 8, Essence = 9, Treadmill = 10,
			Train = 4, HwPumpkin = 2, HwDog = 3, HwMonsters = 5, HwFishing = 6, HwIndex = 2,
		},
		StealTop = function() return 1 end,
	}
	vnhubEnv.IslandWarsSection = wrapSectionForVNHUB(vnhubIslandWarsSec, "VNHUB_IslandWars")
	vnhubEnv.Root = function()
		local ch = q[4].Character
		return ch and ch:FindFirstChild("HumanoidRootPart")
	end
	vnhubEnv.Toggle = function(hObj, _)
		if type(hObj) == "table" then
			if type(hObj.Get) == "function" then
				local ok, v = pcall(hObj.Get, hObj)
				if ok then return v == true end
			end
			return hObj.Value == true
		end
		return false
	end
	vnhubEnv.ShowRow = function(rowObj, txt)
		if type(rowObj) == "table" and type(rowObj.Set) == "function" then
			pcall(rowObj.Set, rowObj, tostring(txt or "Off"))
		end
	end
	vnhubEnv.Notify = function(title, content)
		R:Notify({ Title = tostring(title or "Sự Kiện"), Content = tostring(content or ""), Duration = 4 })
	end
	vnhubEnv.InsideBase = function(pos)
		local p = pos
		if not p then
			local r = vnhubEnv.Root()
			p = r and r.Position
		end
		if not p then return false end
		local ok, res = pcall(function()
			return require(rs.Client.PlotState).ContainsLocalPoint(p)
		end)
		if ok and type(res) == "boolean" then return res end
		return p.X < 552
	end
	vnhubEnv.IsNight = function()
		if type(areaEggCycleMod.IsNightPhase) == "function" then
			local ok, res = pcall(areaEggCycleMod.IsNightPhase, workspace:GetServerTimeNow())
			if ok and res == true then return true end
		end
		return false
	end
	vnhubEnv.WallSealed = function()
		if type(areaEggResetWallMod.IsSealed) == "function" then
			local ok, res = pcall(areaEggResetWallMod.IsSealed)
			if ok and res == true then return true end
		end
		if type(areaEggResetWallMod.IsClosed) == "function" then
			local ok, res = pcall(areaEggResetWallMod.IsClosed)
			if ok and res == true then return true end
		end
		return vnhubEnv.IsNight()
	end
	vnhubEnv.WallOpenDelay = function()
		if type(areaEggResetCycleMod.WallCloseDelaySeconds) == "number" then
			return areaEggResetCycleMod.WallCloseDelaySeconds
		end
		return 5
	end
	vnhubEnv.OnBelt = function()
		local tm = q[9].__VNHUBV4TreadmillManager
		return tm ~= nil and tm.activeTreadmill ~= nil
	end
	vnhubEnv.ExitBelt = function()
		local tm = q[9].__VNHUBV4TreadmillManager
		if tm and tm.activeTreadmill ~= nil then
			pcall(function() tm:_requestUnequip() end)
		end
	end
	vnhubEnv.UndoSwap = function() end
	vnhubEnv.ResetCharacter = function()
		local ch = q[4].Character
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hum then pcall(function() hum.Health = 0 end) end
	end
	vnhubEnv.FlyTo = function(destPos, cancelFn)
		if a and type(a.travelAndWait) == "function" then
			local ok, res = pcall(a.travelAndWait, a, CFrame.new(destPos), { abort = cancelFn })
			if ok and res then return true end
		end
		local r = vnhubEnv.Root()
		if r then
			pcall(function()
				r.CFrame = CFrame.new(destPos)
				r.AssemblyLinearVelocity = Vector3.zero
			end)
			return true
		end
		return false
	end
	vnhubEnv.ClaimMovement = function(tag)
		if g.stealCarrying() then return false end
		local cur = vnhubEnv.Movement.Owner
		if cur == nil or cur == tag or cur == "treadmill" then
			vnhubEnv.Movement.Owner = tag
			return true
		end
		return false
	end
	vnhubEnv.ReleaseMovement = function(tag)
		if vnhubEnv.Movement.Owner == tag then
			vnhubEnv.Movement.Owner = nil
		end
	end
	vnhubEnv.Shield = function(_, on)
		if on then
			local gm = q[9].__VNHUBV4GodMode
			if gm and type(gm.setEnabled) == "function" then pcall(gm.setEnabled, gm, true) end
		end
	end
	vnhubEnv.Combat = {
		PickBat = function(char)
			local cModel = char or q[4].Character
			local bp = q[4]:FindFirstChildOfClass("Backpack")
			for _, cont in ipairs({ cModel, bp }) do
				for _, item in ipairs(cont and cont:GetChildren() or {}) do
					if isWeaponBat(item) then return item end
				end
			end
			return nil
		end,
	}

	local vnhubClosure = function(Q,Q,E)local E=Q[1];
