		end
		local inHw = q[4]:GetAttribute("InHalloweenDimension") == true or q[4]:GetAttribute("HalloweenCarrying") == true
		local hwOverSteal = false
		if not vnhubEnv.Steal.Carrying and type(vnhubEnv.HalloweenOver) == "function" then
			local okO, resO = pcall(vnhubEnv.HalloweenOver, "steal")
			hwOverSteal = okO and resO == true
		end
		local isBusy = inHw or (vnhubEnv.Movement.Owner ~= nil and vnhubEnv.Movement.Owner ~= "treadmill") or hwOverSteal
		q[9].__VNHUBV4EventBusy = isBusy
		if isBusy ~= wasVNHUBBusy then
			wasVNHUBBusy = isBusy
			vnhubWoke = true
			if type(q[9].__VNHUBV4SetStealDeclutter) == "function" then
				pcall(q[9].__VNHUBV4SetStealDeclutter, E.AutoSteal == true and not inHw)
			end
			if not isBusy and E.AutoSteal == true and a ~= nil and not a.destroyed and not a.running then
				task.defer(function()
					if not q[9].__VNHUBV4EventBusy and E.AutoSteal == true and a and not a.destroyed and not a.running then
						pcall(a._schedule, a)
					end
				end)
			end
		end
		vnhubEnv.Steal.Active = E.AutoSteal == true and a ~= nil and (a.running == true or vnhubEnv.Steal.Carrying) and not isBusy
		local nTasks = #vnhubTasks
		if nTasks == 0 then return end
		for _, tObj in ipairs(vnhubTasks) do
			tObj.Gap = tObj.Gap + dt
			tObj.Idle = tObj.Idle + dt
			tObj.Woke = tObj.Woke or vnhubWoke
			if tObj.Hold > 0 then tObj.Hold = tObj.Hold - dt end
		end
		vnhubWoke = false
		local ran = 0
		for _ = 1, nTasks do
			vnhubIdx = vnhubIdx % nTasks + 1
			local tObj = vnhubTasks[vnhubIdx]
			if tObj.Hold <= 0 and ((tObj.Repeat and tObj.Gap >= 0.35) or (tObj.Woke and tObj.Gap >= 0.6) or tObj.Idle >= 5) then
				tObj.Gap = 0
				tObj.Idle = 0
				tObj.Woke = false
				local okT, rep = pcall(tObj.Run, tObj)
				tObj.Repeat = okT and rep == true
				ran = ran + 1
				if ran >= 3 then break end
			end
		end
	end)
end

-- ============================================================================
-- MỤC 7: SERVER (Tìm Máy Chủ Ít Người + Tìm Máy Chủ Người Chơi Mạnh VNHUB)
-- ============================================================================
do
	-- 1. TÌM MÁY CHỦ ÍT NGƯỜI
	local secLowServer = C.section(tabServer, "Tìm Máy Chủ Ít Người", "server", true)
	local lowServerPara = secLowServer:AddParagraph({
		Title = "Trạng Thái Máy Chủ Hiện Tại",
		Content = "Đang kiểm tra số lượng người chơi...",
	})
	C.privateServerMax = secLowServer:AddDropdown({
		Flag = "Server_LowMaxPlayers",
		Title = "Số Người Khác Tối Đa Trong Server",
		Content = "Chỉ tính người chơi khác (KHÔNG tính bạn). Ví dụ chọn 1: server có 1 người khác + bạn là 2 vẫn tính là 1.",
		Options = { "1", "2", "3", "4", "5" },
		Default = "1",
		Multi = false,
		Callback = z(i),
	})
	C.privateServerAuto = secLowServer:AddToggle({
		Flag = "Server_LowAutoHop",
		Title = "Tự Động Đổi Tới Khi Gặp Server Ít Người",
		Content = "Liên tục đổi máy chủ cho tới khi số người chơi khác (không tính bạn) <= mức đã chọn.",
		Default = false,
		Callback = z(n),
	})
	C.hopNoMatch = secLowServer:AddToggle({
		Flag = "Server_HopNoMatch",
		Title = "Đổi Server Khi Hết Trứng Hợp Lệ",
		Content = "Tự động chuyển sang máy chủ vắng khác khi sân không còn trứng khớp bộ lọc.",
		Default = false,
		Callback = z(M),
	})
	C.hopCooldown = secLowServer:AddSlider({
		Flag = "Server_HopCooldown",
		Title = "Thời Gian Chờ Giữa Mỗi Lần Đổi (Giây)",
		Content = "Khoảng nghỉ giữa các lần tự động đổi máy chủ.",
		Min = 1,
		Max = 60,
		Default = 5,
		Increment = 1,
		Callback = z(V),
	})
	secLowServer:AddButton({
		Title = "Tìm & Vào Máy Chủ Ít Người Ngay",
		Content = "Chuyển ngay sang một máy chủ vắng người.",
		Callback = z(function()
			task.spawn(function()
				Y.hopPrivateOnce()
			end)
		end),
	})

	task.spawn(function()
		local lastTxt
		while q[11]() do
			local totalPlayers = #q[1]:GetPlayers()
			local otherPlayers = math.max(0, totalPlayers - 1)
			local txt = string.format(
				"👥 Người chơi khác: %d (Tổng: %d/%d)  •  Mục tiêu <= %s người khác\n⚡ %s",
				otherPlayers,
				totalPlayers,
				q[1].MaxPlayers or 12,
				tostring(Y.privateMax()),
				tostring(Y.privateStatus or "Sẵn sàng")
			)
			if txt ~= lastTxt then
				pcall(function() lowServerPara:SetContent(txt) end)
				lastTxt = txt
			end
			task.wait(1)
		end
	end)

	-- 2. TÌM MÁY CHỦ NGƯỜI CHƠI MẠNH (VNHUB: ServerHop Most Players + Egg Finder)
	local secRichServer = C.section(tabServer, "Tìm Máy Chủ Người Chơi Mạnh (VNHUB)", "trending-up", true)
	local richServerPara = secRichServer:AddParagraph({
		Title = "💎 Radar Máy Chủ Giàu & Trứng Hiếm (VNHUB)",
		Content = "Đang phân tích độ giàu của máy chủ hiện tại...",
	})

	local richState = {
		Auto = false,
		Mode = "Until An Egg Matches",
		MinRarityName = "Cosmic",
		MinIncome = 0,
		SyncFilters = false,
		Visited = { [tostring(game.JobId)] = os.time() },
		Status = "Sẵn sàng",
		Busy = false,
	}

	local function hopRichServer(sortMode)
		if richState.Busy then return end
		richState.Busy = true
		richState.Status = "Đang tìm máy chủ (" .. tostring(sortMode) .. ")..."
		task.spawn(function()
			local httpSvc = game:GetService("HttpService")
			local tpSvc = game:GetService("TeleportService")
			local sortOrder = (sortMode == "Least Players") and "Asc" or "Desc"
			local cursor = ""
			local candidates = {}
			for _ = 1, 4 do
				local url = string.format(
					"https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=%s&excludeFullGames=true&limit=100%s",
					game.PlaceId,
					sortOrder,
					cursor ~= "" and ("&cursor=" .. httpSvc:UrlEncode(cursor)) or ""
				)
				local ok, decoded = pcall(function()
					return httpSvc:JSONDecode(game:HttpGet(url))
				end)
				if not ok or type(decoded) ~= "table" then break end
				for _, srv in ipairs(decoded.data or {}) do
					local id = tostring(srv.id or "")
					local playing = tonumber(srv.playing) or 0
					local maxP = tonumber(srv.maxPlayers) or 0
					if id ~= "" and id ~= tostring(game.JobId) and not richState.Visited[id] and playing < maxP and (maxP - playing) >= 1 then
						table.insert(candidates, { Id = id, Playing = playing, Room = maxP - playing })
					end
				end
				if #candidates > 0 and sortMode ~= "Random" then break end
				cursor = tostring(decoded.nextPageCursor or "")
				if cursor == "" then break end
			end

			if #candidates == 0 then
				richState.Status = "Không tìm thấy máy chủ phù hợp, đang làm mới danh sách..."
				richState.Visited = { [tostring(game.JobId)] = os.time() }
				richState.Busy = false
				return
			end

			table.sort(candidates, function(s1, s2)
				if sortMode == "Least Players" then return s1.Playing < s2.Playing end
				return s1.Playing > s2.Playing
			end)

			local pick = candidates[math.random(1, math.min(#candidates, 15))]
			richState.Visited[pick.Id] = os.time()
			richState.Status = string.format("Đang chuyển sang server đông mạnh (%d người chơi)...", pick.Playing)
			R:Notify({
				Title = "VNHUB Server Hop",
				Content = string.format("Đang vào máy chủ mạnh (%d người chơi)...", pick.Playing),
				Duration = 4,
			})
			pcall(function()
				tpSvc:TeleportToPlaceInstance(game.PlaceId, pick.Id, q[4])
			end)
			task.wait(6)
			richState.Busy = false
		end)
	end

	local function scanServerRichness()
		local bestEggName, bestEggRarity, bestEggRate, matchCount = "Không có", "-", 0, 0
		local minRank = richState.MinRarityName and richState.MinRarityName ~= "Any" and (e.rarityRank(richState.MinRarityName) or 0) or 0
		pcall(function()
			local eggState = require(q[2].Client.EggState)
			local snap = eggState.ReadFieldEggs and eggState.ReadFieldEggs()
			local records = type(snap) == "table" and snap.Records or nil
			if type(records) == "table" then
				for _, rec in pairs(records) do
					if type(rec) == "table" and rec.Uid and rec.State ~= "Claimed" then
						local info = e.resolve(rec)
						local rate = tonumber(E:getAreaEggValue(rec)) or 0
						local rRank = tonumber(info.rarityRank) or 0
						if rate > bestEggRate then
							bestEggRate = rate
							bestEggName = tostring(info.name or rec.AssetCategory)
							bestEggRarity = tostring(info.rarity or "?")
						end
						if rRank >= minRank and (richState.MinIncome <= 0 or rate >= richState.MinIncome) then
							matchCount = matchCount + 1
						end
					end
				end
			end
		end)
		return bestEggName, bestEggRarity, bestEggRate, matchCount
	end

	C.setRichAutoHop = function(val)
		richState.Auto = val == true
		richState.Status = richState.Auto and "Đang quét máy chủ hiện tại..." or "Đã tắt"
	end
	C.richAutoHop = secRichServer:AddToggle({
		Flag = "Server_RichAutoHop",
		Title = "Tự Động Tìm Máy Chủ Người Chơi Mạnh / Trứng Ngon",
		Content = "Tự động quét máy chủ đông người chơi mạnh và dừng lại khi phát hiện trứng đạt chuẩn bộ lọc dưới.",
		Default = false,
		Callback = z(C.setRichAutoHop),
	})
	C.setRichHopMode = function(val)
		richState.Mode = tostring(val or "Until An Egg Matches")
	end
	C.richHopMode = secRichServer:AddDropdown({
		Flag = "Server_RichHopMode",
		Title = "Chế Độ Săn Máy Chủ (Hop Mode)",
		Content = "Until An Egg Matches: dừng khi có trứng khớp  •  Steal Then Hop: trộm xong đổi tiếp.",
		Options = { "Until An Egg Matches", "Steal Then Hop", "After A Rare Spawns" },
		Default = "Until An Egg Matches",
		Multi = false,
		Callback = z(C.setRichHopMode),
	})
	C.setRichMinRarity = function(val)
		richState.MinRarityName = tostring(val or "Cosmic")
	end
	C.richMinRarity = secRichServer:AddDropdown({
		Flag = "Server_RichMinRarity",
		Title = "Độ Hiếm Tối Thiểu Cần Tìm",
		Content = "Tìm máy chủ có trứng đạt từ độ hiếm này trở lên.",
		Options = (function()
			local out = { "Any" }
			for _, rName in ipairs(A) do out[#out + 1] = rName end
			return out
		end)(),
		Default = "Cosmic",
		Multi = false,
		Callback = z(C.setRichMinRarity),
	})
	C.richMinValue = addValueSlider(secRichServer, {
		Flag = "Server_RichMinValueSlider",
		Title = "Thanh Kéo Giá Trị Tối Thiểu Cần Tìm ($/s)",
		Content = "Bỏ qua máy chủ không có trứng đạt mức $/s này (0 = Không lọc giá trị).",
		DefaultRaw = 0,
		OnRaw = function(rawVal)
			richState.MinIncome = rawVal
		end,
	})
	C.setRichSyncFilters = function(val)
		richState.SyncFilters = val == true
		if richState.SyncFilters then
			richState.MinIncome = tonumber(E.StealMinValue) or 0
		end
	end
	C.richSyncFilters = secRichServer:AddToggle({
		Flag = "Server_RichSyncFilters",
		Title = "Đồng Bộ Với Bộ Lọc Auto Steal",
		Content = "Tự động lấy mức giá trị $/s từ Bộ Lọc Trứng của Auto Steal.",
		Default = false,
		Callback = z(C.setRichSyncFilters),
	})
	secRichServer:AddButton({
		Title = "Đổi Sang Máy Chủ Đông & Mạnh Ngay (Most Players)",
		SubTitle = "Mở Bảng Săn Trứng Hiếm",
		Content = "Chuyển ngay sang máy chủ đông người chơi mạnh hoặc mở bảng Hop UI săn Secret/Eternal/Divine.",
		Callback = z(function()
			hopRichServer("Most Players")
		end),
		SubCallback = z(function()
			local hh = Y.hopHunt
			if hh then
				task.spawn(function() pcall(hh.open) end)
			end
		end),
	})

	task.spawn(function()
		local loadedAt = os.clock()
		while q[11]() do
			pcall(function()
				if richState.SyncFilters then
					richState.MinIncome = tonumber(E.StealMinValue) or 0
				end
				local bestName, bestRarity, bestRate, matches = scanServerRichness()
				richServerPara:SetContent(string.format(
					"🔥 Trứng xịn nhất sân: %s [%s] (%s)\n🎯 Khớp bộ lọc săn: %d quả  •  Độ hiếm >= %s  •  Giá trị >= %s\n⚡ Trạng thái: %s",
					bestName,
					bestRarity,
					formatRateShort(bestRate),
					matches,
					tostring(richState.MinRarityName),
					formatRateShort(richState.MinIncome),
					richState.Status
				))
				if richState.Auto and not richState.Busy and (os.clock() - loadedAt) >= 5 then
					if g.stealCarrying() or E.IsPlacing then
						richState.Status = "Đang đợi nhân vật mang trứng về căn cứ..."
					elseif matches > 0 and richState.Mode == "Until An Egg Matches" then
						richState.Status = "🟢 Đã tìm thấy " .. tostring(matches) .. " trứng ngon tại server này!"
					elseif matches == 0 then
						hopRichServer("Most Players")
					end
				end
			end)
			task.wait(1.5)
		end
	end)
end

