	secConfig:AddButton({
		Title = "Share Config (Copy Mã Config)",
		SubTitle = "Import Config (Nạp Mã)",
		Content = "Sao chép toàn bộ cấu hình hiện tại vào Clipboard để gửi cho bạn bè, hoặc nạp từ mã đã dán.",
		Callback = z(function()
			local exported = li and type(li.ExportConfig) == "function" and li:ExportConfig() or nil
			if not exported then
				R:Notify({ Title = "Share Config", Content = "Không thể xuất mã Config!", Duration = 3 })
				return
			end
			local clipFn = type(setclipboard) == "function" and setclipboard or (type(toclipboard) == "function" and toclipboard or nil)
			if clipFn then
